   Claude Fable 5 — Distributed Systems Playground
   One deterministic discrete-event simulation drives every packet, metric, log line,
   chart and state transition on this page. Rendering is a pure projection of sim state.
   ===================================================================================== */

/* ---------------- utils ---------------- */
const DT = 10; // fixed simulation timestep, ms
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const r2 = v => Math.round(v * 100) / 100;
function mulberry32(a){ return function(){ a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
function fmtT(ms){ const m = Math.floor(ms/60000), s = Math.floor(ms/1000)%60, f = Math.floor(ms%1000); return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+'.'+String(f).padStart(3,'0'); }
function fmtClock(ms){ const m = Math.floor(ms/60000), s = Math.floor(ms/1000)%60, d = Math.floor((ms%1000)/100); return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+'.'+d; }
function esc(s){ return String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
function pruneBefore(arr, cut){ while (arr.length && arr[0] < cut) arr.shift(); }

const KEYS = ['user:1','user:2','user:3','cart:4','order:5','order:6','profile:7','invoice:8'];

/* ---------------- scenarios ---------------- */
function staleScript(){
  const s = [{t:900, a:'lag', v:4500, note:'scenario: replica lag raised to 4.5s — watch reads of profile:7 go stale'}];
  for (let i = 0; i < 6; i++){
    s.push({t:1400 + i*1900, a:'hotw'});
    s.push({t:2150 + i*1900, a:'hotr'});
  }
  s.push({t:13600, a:'lag', v:0, note:'scenario: lag removed — replica converging'});
  return s;
}
const SCENARIOS = {
  'healthy':        { label:'Healthy baseline', blurb:'Moderate mixed traffic, stable processing, occasional transient retry.',
                      rate:6,  workers:4, readRatio:.65, lag:600,  script:[] },
  'flash-crowd':    { label:'Flash crowd', blurb:'A sharp demand spike hits the token bucket and queue: rate limiting, backpressure, recovery.',
                      rate:6,  workers:4, readRatio:.6,  lag:600,  script:[
                        {t:2500, a:'rate', v:44, note:'scenario: flash crowd — client demand spikes to 44/s'},
                        {t:2600, a:'burst', v:18},
                        {t:8200, a:'rate', v:6, note:'scenario: crowd passes — demand back to 6/s, backlog drains'} ] },
  'database-outage':{ label:'Database outage', blurb:'Primary fails: circuit opens, writes defer into retry, reads keep flowing from replica. Recovery drains safely.',
                      rate:7,  workers:4, readRatio:.55, lag:600,  script:[
                        {t:2500, a:'db', v:false, note:'scenario: primary database has FAILED'},
                        {t:15000, a:'db', v:true, note:'scenario: primary recovered — probe will close the circuit'} ] },
  'poison-message': { label:'Poison message', blurb:'One malformed write fails every attempt, walks the backoff ladder and dead-letters. Repair &amp; replay it from the DLQ tab.',
                      rate:3,  workers:3, readRatio:.5,  lag:400,  script:[
                        {t:1500, a:'poison', note:'scenario: poison write injected — validation will reject every attempt'} ] },
  'stale-replica':  { label:'Stale replica', blurb:'Writes commit on the primary while a lagging replica serves visibly old versions until convergence.',
                      rate:5,  workers:4, readRatio:.75, lag:0,    script: staleScript() },
};

/* ---------------- topology ---------------- */
const NODES = [
  { id:'clients', title:'CLIENTS',      x:.065, y:.42 },
  { id:'gateway', title:'API GATEWAY',  x:.225, y:.42 },
  { id:'cache',   title:'TTL CACHE',    x:.315, y:.115 },
  { id:'queue',   title:'WORK QUEUE',   x:.435, y:.42 },
  { id:'workers', title:'WORKER POOL',  x:.635, y:.42, big:true },
  { id:'primary', title:'PRIMARY DB',   x:.865, y:.20 },
  { id:'replica', title:'READ REPLICA', x:.865, y:.64 },
  { id:'retry',   title:'RETRY SCHED',  x:.555, y:.80 },
  { id:'dlq',     title:'DEAD LETTERS', x:.30,  y:.80 },
];
const EDGES = [
  { k:'clients>gateway', ax:1, ay:.35, bx:0, by:.35, bend:0,    ms:110 },
  { k:'gateway>clients', ax:0, ay:.72, bx:1, by:.72, bend:.10,  ms:110 },
  { k:'gateway>cache',   ax:.55,ay:0,  bx:.2, by:1,  bend:-.06, ms:80,  label:'probe' },
  { k:'cache>gateway',   ax:.5, ay:1,  bx:.85,by:0,  bend:-.06, ms:80 },
  { k:'cache>queue',     ax:1, ay:.6,  bx:.25,by:0,  bend:-.08, ms:90,  label:'miss' },
  { k:'gateway>queue',   ax:1, ay:.5,  bx:0, by:.5,  bend:0,    ms:90 },
  { k:'queue>workers',   ax:1, ay:.5,  bx:0, by:.5,  bend:0,    ms:90 },
  { k:'workers>primary', ax:1, ay:.28, bx:0, by:.72, bend:-.05, ms:100 },
  { k:'primary>workers', ax:0, ay:.95, bx:1, by:.5,  bend:-.05, ms:100 },
  { k:'workers>replica', ax:1, ay:.72, bx:0, by:.28, bend:-.05, ms:100 },
  { k:'replica>workers', ax:0, ay:.55, bx:1, by:.92, bend:-.07, ms:100 },
  { k:'primary>replica', ax:.62,ay:1,  bx:.62,by:0,  bend:-.14, ms:0,   label:'replication' },
  { k:'workers>cache',   ax:.3, ay:0,  bx:1, by:.55, bend:-.16, ms:140, label:'fill' },
  { k:'primary>cache',   ax:0, ay:.2,  bx:1, by:.2,  bend:-.07, ms:150, label:'invalidate' },
  { k:'workers>retry',   ax:.35,ay:1,  bx:1, by:.35, bend:-.06, ms:110, label:'backoff' },
  { k:'retry>queue',     ax:.3, ay:0,  bx:.6, by:1,  bend:-.05, ms:110, label:'requeue' },
  { k:'retry>dlq',       ax:0, ay:.6,  bx:1, by:.6,  bend:-.05, ms:120, label:'exhausted' },
  { k:'dlq>queue',       ax:.55,ay:0,  bx:.15,by:1,  bend:.06,  ms:130, label:'replay' },
  { k:'workers>gateway', ax:.2, ay:1,  bx:.8, by:1,  bend:-.20, ms:120, label:'responses' },
];
const KIND_COLOR = { read:'#54d0f0', write:'#e879f9', retry:'#f5b04f', hit:'#2ee6a8', stale:'#f5b04f',
                     fail:'#f4587a', dead:'#ff5b7e', ok:'#2ee6a8', rep:'#7c93b5', inv:'#a78bfa', fill:'#54d0f0' };

/* =====================================================================================
   ENGINE — pure deterministic simulation (no DOM, no wall clock)
   ===================================================================================== */
class Engine {
  constructor(seed = 1337, scenario = 'healthy'){
    this.paused = false; this.speed = 1;
    this.resetToken = 0;
    this.reset(seed, scenario);
  }

  reset(seed, scenario){
    seed = (Number(seed) >>> 0) || 1;
    this.seed = seed;
    this.scenario = (scenario in SCENARIOS) ? scenario : 'healthy';
    const sc = SCENARIOS[this.scenario];
    this.rng = mulberry32(seed);
    this.now = 0; this.acc = 0;
    this.evSeq = 0; this.events = [];
    this.reqSeq = 0; this.pktSeq = 0; this.valSeq = 0; this.idemSeq = 0; this.retrySeq = 0;
    this.requests = new Map();
    this.flights = [];
    this.edgeUse = {}; // edgeKey -> {t, kind} for render glow
    this.cfg = {
      dt: DT, serviceMean: 230, serviceJitter: .35,
      queueMax: 60, maxAttempts: 5,
      retryBase: 420, retryFactor: 2, retryJitter: .15,
      cacheTTL: 6000,
      breakerThreshold: 4, breakerCooldown: 4000, halfOpenProbeGap: 1400,
      tokenCap: 32, tokenRate: 24,
      transientWriteFail: .05, transientReadFail: .02,
    };
    this.trafficRate = sc.rate; this.readRatio = sc.readRatio; this.workerCount = sc.workers;
    this.arrivalAcc = 0;
    this.gateway = { tokens: this.cfg.tokenCap, accepted: 0, rejectedRate: 0, rejectedBp: 0, rejectTimes: [] };
    this.queue = []; this.pendingEnqueues = 0;
    this.queueStats = { enq: 0, deq: 0, peak: 0 };
    this.workers = Array.from({length: 12}, (_, i) => ({ id: i + 1, stopped: false, job: null, busySince: 0, done: 0 }));
    this.cache = { map: new Map(), hits: 0, misses: 0, expired: 0, invalidations: 0 };
    this.primary = { up: true, version: 0, commits: 0, dupes: 0, records: new Map(), idem: new Map() };
    this.repLog = []; this.repApplied = 0;
    this.replica = { records: new Map(), lag: sc.lag, appliedVersion: 0, staleReads: 0 };
    this.retryQ = []; this.retryStats = { scheduled: 0, fired: 0 };
    this.dlq = []; this.dlqStamp = 0;
    this.breaker = { state: 'closed', fails: 0, openedAt: 0, probing: false, opens: 0 };
    this.metrics = {
      completed: 0, rejected: 0, failedAttempts: 0, dead: 0, cacheHitResponses: 0,
      compTimes: [], errTimes: [], latSamples: [],
      series: { t: [], thr: [], p95: [], err: [], depth: [] },
      lastThr: 0, lastP95: 0, lastErr: 0,
    };
    this.log = []; this.logSeq = 0;
    this.script = sc.script.slice(); this.scriptIdx = 0;
    this.resetToken++;
    this.addLog('info', 'sim', `reset · seed ${seed} · scenario "${sc.label}"`, { code: 'reset' });
  }

  /* ---------- infrastructure ---------- */
  schedule(t, fn){ this.events.push({ t, seq: ++this.evSeq, fn }); }

  processEvents(){
    let guard = 0;
    while (guard++ < 20000){
      const due = [];
      for (let i = this.events.length - 1; i >= 0; i--){
        if (this.events[i].t <= this.now){ due.push(this.events[i]); this.events.splice(i, 1); }
      }
      if (!due.length) break;
      due.sort((a, b) => a.t - b.t || a.seq - b.seq);
      for (const e of due) e.fn();
    }
  }

  fly(from, to, kind, req, cb, opts){
    const key = from + '>' + to;
    const edge = EDGES.find(e => e.k === key);
    const ms = (opts && opts.ms != null) ? opts.ms : (edge ? edge.ms : 100);
    const f = { id: ++this.pktSeq, edge: key, kind, reqId: req ? req.id : null, t0: this.now, t1: this.now + Math.max(1, ms) };
    this.flights.push(f);
    this.edgeUse[key] = { t: this.now, kind };
    this.schedule(f.t1, () => { const i = this.flights.indexOf(f); if (i >= 0) this.flights.splice(i, 1); if (cb) cb(); });
    return f;
  }
  chain(nodes, kind, req){
    if (nodes.length < 2) return;
    this.fly(nodes[0], nodes[1], kind, req, () => this.chain(nodes.slice(1), kind, req));
  }

  ev(req, code, msg, extra){
    req.history.push(Object.assign({ t: this.now, code, msg }, extra || {}));
    if (req.history.length > 60) req.history.shift();
  }

  addLog(level, comp, msg, o = {}){
    // only high-frequency, low-information codes coalesce — never commits, dedups, stales, deaths
    const canCoalesce = o.code && Engine.COALESCE.has(o.code);
    const last = this.log[this.log.length - 1];
    if (canCoalesce && last && last.code === o.code && last.comp === comp && this.now - last.t < 450){
      last.n = (last.n || 1) + 1; last.t = this.now; return;
    }
    this.log.push({ seq: ++this.logSeq, t: this.now, level, comp, msg, reqId: o.req ? o.req.id : null, code: o.code, n: 1 });
    if (this.log.length > 800) this.log.shift();
  }

  /* ---------- time ---------- */
  step(ms){
    const ticks = Math.max(0, Math.round(ms / DT));
    for (let i = 0; i < ticks; i++) this.tick();
    return this.now;
  }

  tick(){
    this.now += DT;
    // scenario script
    while (this.scriptIdx < this.script.length && this.script[this.scriptIdx].t <= this.now){
      this.runScript(this.script[this.scriptIdx++]);
    }
    // token bucket refill
    const g = this.gateway;
    g.tokens = Math.min(this.cfg.tokenCap, g.tokens + this.cfg.tokenRate * DT / 1000);
    // open traffic
    if (this.trafficRate > 0){
      this.arrivalAcc += this.trafficRate * DT / 1000;
      while (this.arrivalAcc >= 1){ this.arrivalAcc -= 1; this.injectRequest({ auto: true }); }
    }
    // scheduled events (deliveries, service completions, bursts)
    this.processEvents();
    // retry scheduler
    const due = [];
    for (let i = this.retryQ.length - 1; i >= 0; i--){
      if (this.retryQ[i].at <= this.now){ due.push(this.retryQ[i]); this.retryQ.splice(i, 1); }
    }
    due.sort((a, b) => a.at - b.at || a.seq - b.seq);
    for (const e of due) this.fireRetry(e);
    // circuit breaker cooldown
    const b = this.breaker;
    if (b.state === 'open' && this.now >= b.openedAt + this.cfg.breakerCooldown){
      b.state = 'half-open'; b.probing = false;
      this.addLog('info', 'breaker', 'circuit HALF-OPEN — next write becomes the probe', { code: 'cbhalf' });
    }
    // replication apply
    while (this.repApplied < this.repLog.length && this.repLog[this.repApplied].t + this.replica.lag <= this.now){
      const e = this.repLog[this.repApplied++];
      this.replica.records.set(e.key, { key: e.key, value: e.value, version: e.version, at: e.t });
      this.replica.appliedVersion = e.version;
    }
    if (this.repApplied > 400 && this.repApplied === this.repLog.length){ this.repLog.length = 0; this.repApplied = 0; }
    // cache sweep
    if (this.now % 500 === 0){
      for (const [k, e] of this.cache.map){
        if (e.expiresAt <= this.now){ this.cache.map.delete(k); this.cache.expired++; }
      }
    }
    // metrics sample
    if (this.now % 250 === 0) this.sample();
    // prune finished requests
    if (this.now % 5000 === 0){
      for (const [id, r] of this.requests){
        if ((r.state === 'completed' || r.state === 'rejected') && r.endAt != null && this.now - r.endAt > 45000) this.requests.delete(id);
      }
    }
  }

  runScript(s){
    if (s.note) this.addLog('info', 'scenario', s.note, { code: 'scen' });
    switch (s.a){
      case 'rate':   this.trafficRate = s.v; break;
      case 'burst':  this.burst(s.v, false); break;
      case 'db':     this.setPrimaryUp(s.v); break;
      case 'lag':    this.setReplicaLag(s.v); break;
      case 'poison': this.injectRequest({ op: 'write', key: 'invoice:13', idemKey: 'poison-1', value: 'v-poison', poison: true }); break;
      case 'hotw':   this.injectRequest({ op: 'write', key: 'profile:7' }); break;
      case 'hotr':   this.injectRequest({ op: 'read', key: 'profile:7' }); break;
    }
  }

  /* ---------- request lifecycle ---------- */
  injectRequest(o = {}){
    const id = 'R-' + (++this.reqSeq);
    const op = o.op === 'write' ? 'write' : o.op === 'read' ? 'read' : (this.rng() < this.readRatio ? 'read' : 'write');
    const key = o.key || KEYS[Math.floor(this.rng() * KEYS.length)];
    const req = {
      id, op, key,
      tenant: o.tenant || 't-' + (1 + Math.floor(this.rng() * 6)),
      createdAt: this.now, endAt: null, attempts: 0, deferrals: 0,
      poison: !!o.poison, duplicate: !!o.duplicate, fromDlq: false, repaired: false, isProbe: false,
      idemKey: op === 'write' ? (o.idemKey || 'w-' + (++this.idemSeq)) : null,
      value: op === 'write' ? (o.value || 'v' + (++this.valSeq)) : null,
      state: 'in-flight', worker: null, latency: null, result: null, history: [],
    };
    this.requests.set(id, req);
    this.ev(req, 'created', `${op} ${key}` + (req.idemKey ? ` · idem ${req.idemKey}` : '') + (req.poison ? ' · POISON' : '') + (req.duplicate ? ' · duplicate send' : ''));
    this.fly('clients', 'gateway', op === 'read' ? 'read' : 'write', req, () => this.gatewayArrive(req));
    return id;
  }

  burst(n = 18, dupes = false){
    if (!dupes){
      for (let i = 0; i < n; i++){
        this.schedule(this.now + 30 + i * 55 + this.rng() * 25, () => this.injectRequest({}));
      }
      this.addLog('info', 'clients', `burst: ${n} requests over ~${Math.round(n * 55 / 100) / 10}s`, { code: 'burst' });
    } else {
      const pairs = Math.max(2, Math.floor(n / 2));
      for (let i = 0; i < pairs; i++){
        const key = KEYS[Math.floor(this.rng() * KEYS.length)];
        const idem = 'dup-' + (++this.idemSeq);
        const value = 'v' + (++this.valSeq);
        const t0 = this.now + 30 + i * 120 + this.rng() * 20;
        this.schedule(t0, () => this.injectRequest({ op: 'write', key, idemKey: idem, value }));
        this.schedule(t0 + 40 + this.rng() * 160, () => this.injectRequest({ op: 'write', key, idemKey: idem, value, duplicate: true }));
      }
      this.addLog('info', 'clients', `duplicate burst: ${pairs} writes, each sent twice with the same idempotency key`, { code: 'burst' });
    }
  }

  gatewayArrive(req){
    const g = this.gateway;
    if (g.tokens < 1){
      g.rejectedRate++; g.rejectTimes.push(this.now);
      this.metrics.rejected++; this.metrics.errTimes.push(this.now);
      req.state = 'rejected'; req.endAt = this.now;
      this.ev(req, 'rate-limited', 'rejected: no token available in the rate-limiter bucket (429)');
      this.addLog('warn', 'gateway', `${req.id} rejected — token bucket empty (429)`, { req, code: 'rl' });
      this.fly('gateway', 'clients', 'fail', req, null);
      return;
    }
    g.tokens -= 1; g.accepted++;
    this.ev(req, 'admitted', `gateway admitted · ${Math.floor(g.tokens)} tokens left`);
    if (req.op === 'read') this.fly('gateway', 'cache', 'read', req, () => this.cacheProbe(req));
    else this.admitQueue(req, 'gateway');
  }

  cacheProbe(req){
    const c = this.cache, e = c.map.get(req.key);
    if (e && e.expiresAt > this.now){
      c.hits++; e.hits++;
      this.ev(req, 'cache-hit', `cache hit v${e.version} · ttl ${Math.max(0, Math.round(e.expiresAt - this.now))}ms left`);
      this.addLog('info', 'cache', `${req.id} hit ${req.key} v${e.version}`, { req, code: 'hit' });
      this.completeReq(req, { value: e.value, version: e.version, stale: false, via: 'cache' }, 'cache');
      return;
    }
    if (e){
      c.map.delete(req.key); c.expired++;
      this.ev(req, 'cache-expired', `cached entry expired ${Math.round(this.now - e.expiresAt)}ms ago — not counted as a hit`);
      this.addLog('dim', 'cache', `${req.key} expired — evicted, read-through`, { code: 'exp' });
    }
    c.misses++;
    this.ev(req, 'cache-miss', 'cache miss — read-through to replica');
    this.admitQueue(req, 'cache');
  }

  admitQueue(req, fromNode){
    const depth = this.queue.length + this.pendingEnqueues;
    if (depth >= this.cfg.queueMax){
      this.gateway.rejectedBp++; this.gateway.rejectTimes.push(this.now);
      this.metrics.rejected++; this.metrics.errTimes.push(this.now);
      req.state = 'rejected'; req.endAt = this.now;
      this.ev(req, 'shed', `backpressure: queue full (${depth}/${this.cfg.queueMax}) — request shed (503)`);
      this.addLog('warn', 'queue', `${req.id} shed — queue full (${depth}/${this.cfg.queueMax})`, { req, code: 'bp' });
      this.chain(fromNode === 'cache' ? ['cache', 'gateway', 'clients'] : ['gateway', 'clients'], 'fail', req);
      return;
    }
    this.sendToQueue(fromNode, req, req.op === 'read' ? 'read' : 'write');
  }

  sendToQueue(fromNode, req, kind){
    this.pendingEnqueues++;
    this.fly(fromNode, 'queue', kind, req, () => {
      this.pendingEnqueues--;
      this.queue.push(req);
      req.state = 'queued';
      this.queueStats.enq++;
      this.queueStats.peak = Math.max(this.queueStats.peak, this.queue.length);
      this.ev(req, 'enqueued', `enqueued at depth ${this.queue.length}`);
      this.pumpQueue();
    });
  }

  pumpQueue(){
    while (this.queue.length){
      let w = null;
      for (let i = 0; i < this.workerCount; i++){
        const c = this.workers[i];
        if (!c.stopped && !c.job){ w = c; break; }
      }
      if (!w) break;
      const req = this.queue.shift();
      this.queueStats.deq++;
      w.job = req; req.worker = w.id; req.state = 'dispatch';
      this.fly('queue', 'workers', req.attempts > 0 ? 'retry' : (req.op === 'read' ? 'read' : 'write'), req, () => this.workerStart(w, req));
    }
  }

  requeueFront(req, why){
    req.state = 'queued'; req.worker = null;
    this.ev(req, 'requeued', why + ' — returned to queue (at-least-once delivery)');
    this.queue.unshift(req);
    this.queueStats.enq++;
    this.pumpQueue();
  }

  workerStart(w, req){
    if (w.stopped || w.job !== req){ this.requeueFront(req, `worker W${w.id} unavailable on arrival`); this.pumpQueue(); return; }
    if (req.op === 'write'){
      const b = this.breaker;
      const blocked = b.state === 'open' || (b.state === 'half-open' && b.probing);
      if (blocked){
        w.job = null; req.deferrals++;
        const at = this.now + this.cfg.halfOpenProbeGap + Math.floor(this.rng() * 400);
        this.retryQ.push({ reqId: req.id, at, attempt: req.attempts, deferred: true, seq: ++this.retrySeq });
        req.state = 'retry-wait';
        this.ev(req, 'deferred', `circuit ${b.state} — write deferred to T+${fmtT(at)}`);
        this.addLog('warn', 'breaker', `${req.id} deferred — circuit ${b.state}, failing fast`, { req, code: 'defer' });
        this.fly('workers', 'retry', 'retry', req, null);
        this.pumpQueue();
        return;
      }
      if (b.state === 'half-open'){
        b.probing = true; req.isProbe = true;
        this.addLog('info', 'breaker', `${req.id} chosen as half-open probe`, { req, code: 'probe' });
      }
    }
    req.attempts++; req.state = 'processing'; w.busySince = this.now;
    const mult = req.op === 'write' ? 1.25 : 1;
    const svc = Math.round(this.cfg.serviceMean * mult * (1 + this.cfg.serviceJitter * (this.rng() * 2 - 1)));
    this.ev(req, 'processing', `worker W${w.id} · attempt ${req.attempts}/${this.cfg.maxAttempts} · service ${svc}ms`);
    this.schedule(this.now + svc, () => this.workerFinish(w, req));
  }

  workerFinish(w, req){
    if (w.job !== req || w.stopped) return; // crash mid-service already handled
    req.state = 'db-wait';
    if (req.op === 'write') this.fly('workers', 'primary', 'write', req, () => this.primaryArrive(w, req));
    else this.fly('workers', 'replica', 'read', req, () => this.replicaArrive(w, req));
  }

  primaryArrive(w, req){
    const p = this.primary;
    let o;
    if (!p.up){
      o = { ok: false, reason: 'primary unavailable (connection refused)' };
      this.addLog('bad', 'primary', `${req.id} write failed — primary is DOWN`, { req, code: 'pdown' });
      this.breakerFail(req);
    } else if (req.poison){
      o = { ok: false, reason: 'payload rejected by validation (poison message)' };
      this.addLog('bad', 'primary', `${req.id} poison payload rejected by validation`, { req, code: 'poison' });
      this.breakerOk(req);
    } else if (this.rng() < this.cfg.transientWriteFail){
      o = { ok: false, reason: 'row lock timeout (transient)' };
      this.addLog('warn', 'primary', `${req.id} transient failure — row lock timeout`, { req, code: 'tw' });
      this.breakerFail(req);
    } else if (p.idem.has(req.idemKey)){
      const prev = p.idem.get(req.idemKey);
      p.dupes++;
      o = { ok: true, dup: true, version: prev.version, value: prev.value, via: 'primary' };
      this.ev(req, 'dedup', `write skipped — idempotency key ${req.idemKey} already committed as v${prev.version} by ${prev.reqId}`);
      this.addLog('info', 'primary', `${req.id} duplicate prevented — idem ${req.idemKey} already committed (v${prev.version})`, { req, code: 'dup' });
      this.breakerOk(req);
    } else {
      const version = ++p.version;
      p.records.set(req.key, { key: req.key, value: req.value, version, at: this.now, by: req.id, idemKey: req.idemKey });
      p.idem.set(req.idemKey, { version, reqId: req.id, value: req.value });
      p.commits++;
      this.repLog.push({ key: req.key, value: req.value, version, t: this.now });
      if (this.replica.lag > 0) this.fly('primary', 'replica', 'rep', req, null, { ms: this.replica.lag });
      o = { ok: true, version, value: req.value, via: 'primary' };
      this.ev(req, 'committed', `v${version} committed for ${req.key}`);
      this.addLog('info', 'primary', `${req.id} committed ${req.key} v${version}`, { req, code: 'commit' });
      if (this.cache.map.has(req.key)){
        this.cache.map.delete(req.key); this.cache.invalidations++;
        this.fly('primary', 'cache', 'inv', req, null);
        this.addLog('dim', 'cache', `${req.key} invalidated after write v${version}`, { code: 'inv' });
      }
      this.breakerOk(req);
    }
    this.fly('primary', 'workers', o.ok ? 'ok' : 'fail', req, () => this.workerResp(w, req, o));
  }

  replicaArrive(w, req){
    if (this.rng() < this.cfg.transientReadFail){
      const o = { ok: false, reason: 'replica read timeout (transient)' };
      this.addLog('warn', 'replica', `${req.id} transient read timeout`, { req, code: 'tr' });
      this.fly('replica', 'workers', 'fail', req, () => this.workerResp(w, req, o));
      return;
    }
    const rec = this.replica.records.get(req.key);
    const prim = this.primary.records.get(req.key);
    const stale = !!(prim && (!rec || rec.version < prim.version));
    if (stale){
      this.ev(req, 'stale-read', `replica returned v${rec ? rec.version : 0} — has not applied v${prim.version} yet`);
      this.addLog('warn', 'replica', `${req.id} STALE read ${req.key}: v${rec ? rec.version : 0} vs primary v${prim.version}`, { req, code: 'stale' });
    } else {
      this.ev(req, 'replica-read', `read ${req.key} → ${rec ? 'v' + rec.version : 'no record'}`);
    }
    const o = { ok: true, value: rec ? rec.value : null, version: rec ? rec.version : 0, stale, hasRec: !!rec, via: 'replica' };
    this.fly('replica', 'workers', stale ? 'stale' : 'ok', req, () => this.workerResp(w, req, o));
  }

  workerResp(w, req, o){
    if (w.job !== req || w.stopped){
      this.addLog('warn', 'workers', `ack for ${req.id} reached stopped worker W${w.id} — dropped (work already requeued; idempotency will dedupe)`, { code: 'orphan' });
      return;
    }
    w.job = null; w.done++;
    this.pumpQueue();
    if (o.ok){
      if (req.op === 'read' && o.hasRec){
        this.cache.map.set(req.key, { value: o.value, version: o.version, expiresAt: this.now + this.cfg.cacheTTL, cachedAt: this.now, hits: 0 });
        this.fly('workers', 'cache', 'fill', req, null);
      }
      this.completeReq(req, o, 'workers');
    } else {
      this.failAttempt(req, o);
    }
  }

  failAttempt(req, o){
    this.metrics.failedAttempts++; this.metrics.errTimes.push(this.now);
    this.ev(req, 'failed', `attempt ${req.attempts} failed: ${o.reason}`);
    if (req.attempts >= this.cfg.maxAttempts){
      req.state = 'dead-letter-transit';
      this.addLog('bad', 'retry', `${req.id} exhausted ${req.attempts} attempts — routing to dead-letter queue`, { req, code: 'dlq' });
      this.fly('workers', 'retry', 'dead', req, () => this.fly('retry', 'dlq', 'dead', req, () => {
        req.state = 'dead-lettered'; req.endAt = this.now;
        this.metrics.dead++;
        this.dlq.push({ reqId: req.id, key: req.key, reason: o.reason, at: this.now, attempts: req.attempts });
        this.dlqStamp++;
        this.ev(req, 'dead-lettered', `after ${req.attempts} attempts: ${o.reason}`);
        this.addLog('bad', 'dlq', `${req.id} dead-lettered (${o.reason})`, { req, code: 'dead' });
      }));
    } else {
      const delay = Math.round(this.cfg.retryBase * Math.pow(this.cfg.retryFactor, req.attempts - 1) * (1 + this.cfg.retryJitter * this.rng()));
      const at = this.now + delay;
      this.retryQ.push({ reqId: req.id, at, attempt: req.attempts, seq: ++this.retrySeq });
      this.retryStats.scheduled++;
      req.state = 'retry-wait';
      this.ev(req, 'retry-scheduled', `retry #${req.attempts} scheduled for T+${fmtT(at)} (backoff ${delay}ms)`, { at, delay });
      this.addLog('warn', 'retry', `${req.id} retry in ${delay}ms — attempt ${req.attempts} failed (${o.reason})`, { req, code: 'retry' });
      this.fly('workers', 'retry', 'retry', req, null);
    }
  }

  fireRetry(e){
    const req = this.requests.get(e.reqId);
    if (!req || req.state !== 'retry-wait') return;
    if (req.op === 'write' && this.breaker.state === 'open'){
      e.at = this.now + this.cfg.halfOpenProbeGap + Math.floor(this.rng() * 300);
      req.deferrals++;
      this.retryQ.push(e);
      this.addLog('dim', 'retry', `${req.id} still deferred — circuit open`, { code: 'redefer' });
      return;
    }
    if (this.queue.length + this.pendingEnqueues >= this.cfg.queueMax){
      e.at = this.now + 800;
      this.retryQ.push(e);
      this.addLog('dim', 'retry', `${req.id} requeue delayed — queue full`, { code: 'rqfull' });
      return;
    }
    this.retryStats.fired++;
    req.state = 'requeue-transit';
    this.ev(req, 'retry-fired', `retry #${e.attempt} fired`);
    this.sendToQueue('retry', req, 'retry');
  }

  replayDlq(reqId, repair = true){
    const i = this.dlq.findIndex(d => d.reqId === reqId);
    if (i < 0) return false;
    const req = this.requests.get(reqId);
    if (!req){ this.dlq.splice(i, 1); this.dlqStamp++; return false; }
    if (this.queue.length + this.pendingEnqueues >= this.cfg.queueMax){
      this.addLog('warn', 'dlq', `replay of ${reqId} blocked — queue full`, { code: 'rpfull' });
      return false;
    }
    this.dlq.splice(i, 1); this.dlqStamp++;
    if (repair && req.poison){
      req.poison = false; req.repaired = true;
      this.ev(req, 'repaired', 'poison condition cleared by operator');
      this.addLog('info', 'dlq', `${req.id} payload repaired — poison flag cleared`, { req, code: 'repair' });
    }
    req.attempts = 0; req.fromDlq = true;
    req.state = 'requeue-transit';
    this.ev(req, 'replayed', repair ? 'replayed from DLQ (repaired)' : 'replayed from DLQ as-is');
    this.addLog('info', 'dlq', `${req.id} replayed from dead-letter queue${repair ? ' (repaired)' : ' (as-is)'}`, { req, code: 'replay' });
    this.sendToQueue('dlq', req, 'retry');
    return true;
  }

  completeReq(req, o, fromNode){
    req.state = 'completed'; req.endAt = this.now;
    const lat = this.now - req.createdAt;
    req.latency = lat;
    req.result = { value: o.value == null ? null : o.value, version: o.version || 0, stale: !!o.stale, via: o.via || fromNode, dedup: !!o.dup };
    this.metrics.completed++;
    this.metrics.compTimes.push(this.now);
    this.metrics.latSamples.push({ t: this.now, v: lat });
    if (o.stale) this.replica.staleReads++;
    if (o.via === 'cache') this.metrics.cacheHitResponses++;
    this.ev(req, 'completed',
      (o.via === 'cache' ? 'served from cache' : o.dup ? 'acknowledged via idempotent dedup' : req.op) +
      ` in ${lat}ms` + (o.stale ? ' · STALE' : '') + (o.version ? ` · v${o.version}` : ''));
    if (req.fromDlq){
      this.addLog('info', 'dlq', `dead-letter replay succeeded for ${req.id}` + (req.repaired ? ' after the poison condition was cleared' : ''), { req, code: 'replayok' });
    }
    const kind = o.via === 'cache' ? 'hit' : (o.stale ? 'stale' : 'ok');
    this.chain(fromNode === 'cache' ? ['cache', 'gateway', 'clients'] : ['workers', 'gateway', 'clients'], kind, req);
  }

  /* ---------- circuit breaker ---------- */
  breakerFail(req){
    const b = this.breaker;
    if (b.state === 'half-open'){
      b.state = 'open'; b.openedAt = this.now; b.probing = false; b.opens++;
      if (req) req.isProbe = false;
      this.addLog('bad', 'breaker', 'half-open probe FAILED — circuit re-opened', { code: 'cbopen' });
      return;
    }
    b.fails++;
    if (b.state === 'closed' && b.fails >= this.cfg.breakerThreshold){
      b.state = 'open'; b.openedAt = this.now; b.opens++;
      this.addLog('bad', 'breaker', `circuit OPENED after ${b.fails} consecutive primary failures`, { code: 'cbopen' });
    }
  }
  breakerOk(req){
    const b = this.breaker;
    if (b.state === 'half-open'){
      b.state = 'closed'; b.fails = 0; b.probing = false;
      if (req) req.isProbe = false;
      this.addLog('info', 'breaker', 'probe succeeded — circuit CLOSED', { code: 'cbclose' });
    } else {
      b.fails = 0;
    }
  }

  /* ---------- operator actions ---------- */
  setPrimaryUp(up){
    up = !!up;
    if (this.primary.up === up) return;
    this.primary.up = up;
    this.addLog(up ? 'info' : 'bad', 'primary', up ? 'primary database RECOVERED' : 'primary database FAILED — refusing all commits', { code: 'ptoggle' });
  }
  setReplicaLag(ms){
    ms = clamp(Math.round(ms) || 0, 0, 60000);
    this.replica.lag = ms;
    this.flights = this.flights.filter(f => f.kind !== 'rep');
    for (let i = this.repApplied; i < this.repLog.length; i++){
      const e = this.repLog[i];
      if (e.t + ms > this.now){
        this.flights.push({ id: ++this.pktSeq, edge: 'primary>replica', kind: 'rep', reqId: null, t0: e.t, t1: e.t + ms });
      }
    }
    this.addLog('info', 'replica', ms > 0 ? `replication lag set to ${ms}ms` : 'replication lag cleared — converging', { code: 'lag' });
  }
  setTraffic(r){ this.trafficRate = clamp(Math.round(r), 0, 60); }
  setTokenRate(r){ this.cfg.tokenRate = clamp(Math.round(r), 1, 60); this.addLog('info', 'gateway', `token refill rate set to ${this.cfg.tokenRate}/s`, { code: 'trate' }); }
  setWorkerCount(n){
    n = clamp(Math.round(n), 1, 12);
    if (n === this.workerCount) return;
    if (n < this.workerCount){
      for (let i = n; i < this.workerCount; i++){
        const w = this.workers[i];
        if (w.job){ const req = w.job; w.job = null; this.requeueFront(req, `worker W${w.id} removed from pool`); }
      }
    }
    this.workerCount = n;
    this.addLog('info', 'workers', `worker pool resized to ${n}`, { code: 'wsize' });
    this.pumpQueue();
  }
  stopWorker(id){
    let w = id ? this.workers[id - 1] : null;
    if (!w || w.stopped){
      w = null;
      for (let i = 0; i < this.workerCount; i++){ const c = this.workers[i]; if (!c.stopped && c.job){ w = c; break; } }
      if (!w) for (let i = 0; i < this.workerCount; i++){ const c = this.workers[i]; if (!c.stopped){ w = c; break; } }
    }
    if (!w || w.stopped) return 0;
    w.stopped = true;
    let extra = '';
    if (w.job){ const req = w.job; w.job = null; this.requeueFront(req, `worker W${w.id} stopped mid-flight`); extra = ` — ${req.id} requeued, no acknowledged work lost`; }
    this.addLog('warn', 'workers', `worker W${w.id} STOPPED${extra}`, { code: 'wstop' });
    return w.id;
  }
  restoreWorker(id){
    let w = id ? this.workers[id - 1] : null;
    if (!w || !w.stopped){
      w = null;
      for (let i = 0; i < 12; i++){ if (this.workers[i].stopped){ w = this.workers[i]; break; } }
    }
    if (!w) return 0;
    w.stopped = false;
    this.addLog('info', 'workers', `worker W${w.id} restored`, { code: 'wrest' });
    this.pumpQueue();
    return w.id;
  }

  /* ---------- metrics ---------- */
  sample(){
    const m = this.metrics, now = this.now;
    pruneBefore(m.compTimes, now - 2200);
    pruneBefore(m.errTimes, now - 2600);
    while (m.latSamples.length && m.latSamples[0].t < now - 5200) m.latSamples.shift();
    pruneBefore(this.gateway.rejectTimes, now - 3000);
    let thr = 0, comps2 = 0;
    for (const t of m.compTimes){ if (t > now - 1000) thr++; if (t > now - 2000) comps2++; }
    let errs2 = 0;
    for (const t of m.errTimes){ if (t > now - 2000) errs2++; }
    const err = (comps2 + errs2) === 0 ? 0 : 100 * errs2 / (comps2 + errs2);
    const lats = m.latSamples.map(s => s.v).sort((a, b) => a - b);
    const p95 = lats.length ? lats[Math.max(0, Math.ceil(lats.length * 0.95) - 1)] : 0;
    const s = m.series;
    s.t.push(now); s.thr.push(thr); s.p95.push(p95); s.err.push(r2(err)); s.depth.push(this.queue.length);
    if (s.t.length > 241){ s.t.shift(); s.thr.shift(); s.p95.shift(); s.err.shift(); s.depth.shift(); }
    m.lastThr = thr; m.lastP95 = p95; m.lastErr = err;
  }

  systemState(){
    if (!this.primary.up || this.breaker.state === 'open') return 'failed';
    if (this.gateway.rejectTimes.length > 2) return 'throttled';
    let stopped = false;
    for (let i = 0; i < this.workerCount; i++) if (this.workers[i].stopped) stopped = true;
    const pendingRep = this.repLog.length - this.repApplied;
    if (this.queue.length >= .6 * this.cfg.queueMax || stopped || this.breaker.state === 'half-open' || (this.replica.lag >= 1500 && pendingRep > 0)) return 'degraded';
    return 'nominal';
  }

  snapshot(){
    const m = this.metrics;
    const hr = (this.cache.hits + this.cache.misses) === 0 ? 0 : this.cache.hits / (this.cache.hits + this.cache.misses);
    const sortRecs = map => [...map.values()].sort((a, b) => a.key < b.key ? -1 : 1).slice(0, 64)
      .map(r => ({ key: r.key, value: r.value, version: r.version, at: Math.round(r.at) }));
    let active = 0;
    for (const r of this.requests.values()){
      if (r.state !== 'completed' && r.state !== 'rejected' && r.state !== 'dead-lettered') active++;
    }
    let avg = 0;
    if (m.latSamples.length){ for (const s of m.latSamples) avg += s.v; avg /= m.latSamples.length; }
    return {
      time: this.now, seed: this.seed, scenario: this.scenario, paused: this.paused, speed: this.speed,
      systemState: this.systemState(),
      gateway: { tokens: r2(this.gateway.tokens), capacity: this.cfg.tokenCap, refillPerSec: this.cfg.tokenRate,
                 accepted: this.gateway.accepted, rejectedRateLimit: this.gateway.rejectedRate, rejectedBackpressure: this.gateway.rejectedBp },
      queue: { depth: this.queue.length, inTransit: this.pendingEnqueues, max: this.cfg.queueMax,
               enqueued: this.queueStats.enq, dequeued: this.queueStats.deq, peak: this.queueStats.peak },
      workers: this.workers.slice(0, this.workerCount).map(w => ({ id: w.id, state: w.stopped ? 'stopped' : (w.job ? 'busy' : 'idle'), req: w.job ? w.job.id : null, done: w.done })),
      cache: { entries: this.cache.map.size, hits: this.cache.hits, misses: this.cache.misses,
               expired: this.cache.expired, invalidations: this.cache.invalidations, hitRate: r2(hr), ttlMs: this.cfg.cacheTTL },
      primary: { up: this.primary.up, version: this.primary.version, commits: this.primary.commits,
                 duplicatesPrevented: this.primary.dupes, records: sortRecs(this.primary.records) },
      replica: { lagMs: this.replica.lag, appliedVersion: this.replica.appliedVersion,
                 pendingOps: this.repLog.length - this.repApplied, staleReads: this.replica.staleReads, records: sortRecs(this.replica.records) },
      retryScheduler: { pending: this.retryQ.map(e => ({ req: e.reqId, at: Math.round(e.at), attempt: e.attempt })).sort((a, b) => a.at - b.at || (a.req < b.req ? -1 : 1)),
                        scheduled: this.retryStats.scheduled, fired: this.retryStats.fired },
      circuitBreaker: { state: this.breaker.state, consecutiveFailures: this.breaker.fails,
                        openedAt: Math.round(this.breaker.openedAt), timesOpened: this.breaker.opens },
      deadLetterQueue: this.dlq.map(d => ({ req: d.reqId, key: d.key, reason: d.reason, at: Math.round(d.at), attempts: d.attempts })),
      metrics: { completed: m.completed, rejected: m.rejected, failedAttempts: m.failedAttempts, deadLettered: m.dead,
                 staleReads: this.replica.staleReads, duplicatesPrevented: this.primary.dupes,
                 cacheHitRate: r2(hr), throughputPerSec: m.lastThr, p95LatencyMs: r2(m.lastP95),
                 errorRatePct: r2(m.lastErr), avgLatencyMs: r2(avg) },
      requests: { created: this.reqSeq, active, inFlightPackets: this.flights.length },
    };
  }
}

Engine.COALESCE = new Set(['rl', 'bp', 'defer', 'redefer', 'rqfull', 'exp', 'inv', 'hit', 'tr', 'tw', 'pdown']);

/* The exact function the animation loop uses — also exercised by the self-test. */
function frameAdvance(eng, wallDtMs){
  if (eng.paused) return 0;
  eng.acc += Math.min(wallDtMs, 250) * eng.speed;
  const ticks = Math.floor(eng.acc / DT);
  eng.acc -= ticks * DT;
  for (let i = 0; i < ticks; i++) eng.tick();
  return ticks;
}

/* =====================================================================================
   SELF-TEST — isolated engines, same simulation code paths, no hard-coded outcomes
   ===================================================================================== */
function runSelfTests(){
  const tests = [];
  const T = (name, fn) => {
    try { const r = fn(); tests.push({ name, pass: !!r.pass, detail: String(r.detail || '') }); }
    catch (err){ tests.push({ name, pass: false, detail: 'exception: ' + err.message }); }
  };
  const mk = (seed, scen) => { const e = new Engine(seed, scen); e.paused = false; return e; };

  T('identical seed & actions → identical snapshots', () => {
    const run = () => {
      const e = mk(42, 'healthy');
      e.step(1500);
      e.injectRequest({ op: 'write', key: 'user:1', idemKey: 't1-i1', value: 't1-v' });
      e.step(2500);
      e.injectRequest({ op: 'read', key: 'user:1' });
      e.step(3000);
      return JSON.stringify(e.snapshot());
    };
    const a = run(), b = run();
    return { pass: a === b, detail: a === b ? 'two scripted 7s runs are byte-identical' : 'snapshots diverged' };
  });

  T('pause blocks animation-loop time advance', () => {
    const e = mk(7, 'healthy');
    e.step(500);
    const t0 = e.now;
    e.paused = true;
    frameAdvance(e, 400); frameAdvance(e, 400);
    const held = e.now === t0;
    e.paused = false;
    frameAdvance(e, 100);
    return { pass: held && e.now > t0, detail: `held at ${t0}ms while paused; ${e.now}ms after resume` };
  });

  T('duplicate idempotency key commits at most once', () => {
    const e = mk(9, 'healthy'); e.trafficRate = 0;
    const c0 = e.primary.commits;
    e.injectRequest({ op: 'write', key: 'order:5', idemKey: 'dup-test', value: 'vX' });
    e.injectRequest({ op: 'write', key: 'order:5', idemKey: 'dup-test', value: 'vX' });
    e.step(9000);

    const commits = e.primary.commits - c0;
    return { pass: commits === 1 && e.primary.dupes >= 1, detail: `${commits} commit, ${e.primary.dupes} duplicate prevented` };
  });

  T('failed primary never reports a successful commit', () => {
    const e = mk(11, 'healthy'); e.trafficRate = 0;
    e.setPrimaryUp(false);
    const c0 = e.primary.commits;
    const id = e.injectRequest({ op: 'write', key: 'cart:4', idemKey: 'down-1', value: 'vD' });
    e.step(6000);
    const req = e.requests.get(id);
    const noneWhileDown = e.primary.commits === c0 && req.state !== 'completed';
    e.setPrimaryUp(true);
    e.step(15000);
    const recovered = req.state === 'completed' && e.primary.commits === c0 + 1;
    return { pass: noneWhileDown && recovered, detail: `0 commits while down; exactly 1 after recovery (${req.state})` };
  });

  // one poison engine feeds tests 5–7
  const pe = mk(13, 'healthy'); pe.trafficRate = 0;
  const pid = pe.injectRequest({ op: 'write', key: 'invoice:13', idemKey: 'poison-t', value: 'vP', poison: true });
  pe.step(20000);
  const preq = pe.requests.get(pid);

  T('retry timestamps grow by exponential backoff', () => {
    const delays = preq.history.filter(h => h.code === 'retry-scheduled').map(h => h.delay);
    const inc = delays.length >= 3 && delays.every((d, i) => i === 0 || d > delays[i - 1]);
    return { pass: inc, detail: 'delays ' + delays.join(' → ') + ' ms' };
  });

  T('poison work reaches DLQ after attempt limit', () => {
    const ok = preq.state === 'dead-lettered' && pe.dlq.length === 1 && preq.attempts === pe.cfg.maxAttempts;
    return { pass: ok, detail: `state ${preq.state} after ${preq.attempts}/${pe.cfg.maxAttempts} attempts` };
  });

  T('DLQ replay completes after poison is cleared', () => {
    pe.replayDlq(pid, true);
    pe.step(8000);
    const ok = preq.state === 'completed' && pe.dlq.length === 0 && pe.primary.records.has('invoice:13');
    return { pass: ok, detail: `replayed → ${preq.state}, record ${pe.primary.records.has('invoice:13') ? 'committed' : 'missing'}` };
  });

  T('expired cache entries never count as hits', () => {
    const e = mk(17, 'healthy'); e.trafficRate = 0;
    e.injectRequest({ op: 'write', key: 'user:2', idemKey: 'c-1', value: 'vC' });
    e.step(3000);
    e.injectRequest({ op: 'read', key: 'user:2' });
    e.step(2500); // miss → fills cache
    const h0 = e.cache.hits;
    e.injectRequest({ op: 'read', key: 'user:2' });
    e.step(2000); // within TTL → hit
    const hitOk = e.cache.hits === h0 + 1;
    e.step(e.cfg.cacheTTL + 1000); // let it expire
    e.injectRequest({ op: 'read', key: 'user:2' });
    e.step(2500);
    const ok = hitOk && e.cache.hits === h0 + 1 && e.cache.expired >= 1;
    return { pass: ok, detail: `1 hit inside TTL, expired entry re-missed (hits ${e.cache.hits}, expired ${e.cache.expired})` };
  });

  T('replica converges after lag removed', () => {
    const e = mk(19, 'healthy'); e.trafficRate = 0;
    e.setReplicaLag(60000);
    e.injectRequest({ op: 'write', key: 'profile:7', idemKey: 'r-1', value: 'vR' });
    e.step(5000);
    const prim = e.primary.records.get('profile:7');
    const behind = !!prim && !e.replica.records.has('profile:7');
    e.setReplicaLag(0);
    e.step(500);
    const rec = e.replica.records.get('profile:7');
    const ok = behind && !!rec && rec.version === prim.version && (e.repLog.length - e.repApplied) === 0;
    return { pass: ok, detail: ok ? `replica caught up to v${rec.version}, 0 pending` : 'replica did not converge' };
  });

  T('all metrics stay finite through a flash crowd', () => {
    const e = mk(23, 'flash-crowd');
    e.step(30000);
    const bad = [];
    (function walk(o, p){
      for (const k in o){
        const v = o[k];
        if (typeof v === 'number'){ if (!Number.isFinite(v)) bad.push(p + k); }
        else if (v && typeof v === 'object') walk(v, p + k + '.');
      }
    })(e.snapshot(), '');
    return { pass: bad.length === 0, detail: bad.length ? 'non-finite: ' + bad.join(', ') : `snapshot clean after 30s @44/s (${e.metrics.completed} completed)` };
  });

  T('worker crash loses no acknowledged work', () => {
    const e = mk(29, 'healthy'); e.trafficRate = 0;
    const c0 = e.primary.commits;
    const id = e.injectRequest({ op: 'write', key: 'order:6', idemKey: 'w-1', value: 'vW' });
    e.step(400);
    e.stopWorker();
    e.step(12000);
    const req = e.requests.get(id);
    const ok = req.state === 'completed' && e.primary.commits === c0 + 1;
    return { pass: ok, detail: `crash mid-flight → ${req.state}, ${e.primary.commits - c0} commit (idempotent dedup)` };
  });

  return { passed: tests.every(t => t.pass), tests };
}

/* =====================================================================================
   APP — rendering & interaction (visual projection of engine state only)
   ===================================================================================== */
const $ = id => document.getElementById(id);
const engine = new Engine(1337, 'healthy');
const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');

const stage = $('stage'), cv = $('topo'), ctx = cv.getContext('2d');
let CW = 0, CH = 0, geom = null;

function resize(){
  const dpr = Math.min(devicePixelRatio || 1, 2.5);
  const r = stage.getBoundingClientRect();
  CW = Math.max(200, r.width); CH = Math.max(160, r.height);
  cv.width = Math.round(CW * dpr); cv.height = Math.round(CH * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  geom = computeGeom();
}
new ResizeObserver(resize).observe(stage);

function computeGeom(){
  const nw = clamp(CW * .118, 64, 150), nh = clamp(CH * .155, 50, 88);
  const nodes = {};
  for (const n of NODES){
    const w = n.big ? nw * 1.3 : nw, h = n.big ? nh * 1.5 : nh;
    nodes[n.id] = { id: n.id, title: n.title, x: n.x * CW - w / 2, y: n.y * CH - h / 2, w, h };
  }
  const edges = {};
  for (const e of EDGES){
    const A = nodes[e.k.split('>')[0]], B = nodes[e.k.split('>')[1]];
    const p0 = { x: A.x + e.ax * A.w, y: A.y + e.ay * A.h };
    const p1 = { x: B.x + e.bx * B.w, y: B.y + e.by * B.h };
    const dx = p1.x - p0.x, dy = p1.y - p0.y, len = Math.hypot(dx, dy) || 1;
    const c = { x: (p0.x + p1.x) / 2 + (dy / len) * e.bend * len, y: (p0.y + p1.y) / 2 - (dx / len) * e.bend * len };
    edges[e.k] = { p0, p1, c, cfg: e };
  }
  return { nodes, edges };
}
function bez(e, u){
  const a = (1 - u) * (1 - u), b = 2 * (1 - u) * u, c = u * u;
  return { x: a * e.p0.x + b * e.c.x + c * e.p1.x, y: a * e.p0.y + b * e.c.y + c * e.p1.y };
}
function bezTan(e, u){
  const x = 2 * (1 - u) * (e.c.x - e.p0.x) + 2 * u * (e.p1.x - e.c.x);
  const y = 2 * (1 - u) * (e.c.y - e.p0.y) + 2 * u * (e.p1.y - e.c.y);
  const l = Math.hypot(x, y) || 1;
  return { x: x / l, y: y / l };
}

/* ---------- selection ---------- */
let sel = null; // {type:'req'|'node'|'record'|'breaker', ...}
function selectReq(id){ const r = engine.requests.get(id); if (r){ sel = { type: 'req', id }; setTab('insp'); renderInspector(true); } }

/* ---------- drawing ---------- */
function drawScene(){
  if (!geom) return;
  const now = engine.now;
  ctx.clearRect(0, 0, CW, CH);
  // dotted backdrop
  ctx.fillStyle = '#16233b55';
  const gs = 26;
  for (let x = gs; x < CW; x += gs) for (let y = gs; y < CH; y += gs) ctx.fillRect(x, y, 1.2, 1.2);

  // edges
  for (const k in geom.edges){
    const e = geom.edges[k];
    const use = engine.edgeUse[k];
    const age = use ? now - use.t : 1e9;
    const hot = age < 700;
    ctx.beginPath();
    ctx.moveTo(e.p0.x, e.p0.y);
    ctx.quadraticCurveTo(e.c.x, e.c.y, e.p1.x, e.p1.y);
    ctx.lineWidth = hot ? 1.8 : 1.1;
    ctx.strokeStyle = hot ? (KIND_COLOR[use.kind] || '#54d0f0') + '66' : '#8caad422';
    ctx.stroke();
    // direction chevron
    const m = bez(e, .54), t = bezTan(e, .54);
    ctx.beginPath();
    ctx.moveTo(m.x - t.x * 5 - t.y * 3.4, m.y - t.y * 5 + t.x * 3.4);
    ctx.lineTo(m.x + t.x * 3.4, m.y + t.y * 3.4);
    ctx.lineTo(m.x - t.x * 5 + t.y * 3.4, m.y - t.y * 5 - t.x * 3.4);
    ctx.strokeStyle = hot ? (KIND_COLOR[use.kind] || '#54d0f0') + 'aa' : '#8caad435';
    ctx.lineWidth = 1.2;
    ctx.stroke();
    if (e.cfg.label){
      const lp = bez(e, .5);
      ctx.font = '500 9px ' + 'ui-monospace,Menlo,monospace';
      ctx.fillStyle = '#5a7089' + (hot ? 'ee' : '99');
      ctx.textAlign = 'center';
      ctx.fillText(e.cfg.label, lp.x, lp.y - 5);
    }
  }

  drawBreakerGlyph(now);
  for (const id in geom.nodes) drawNode(geom.nodes[id], now);

  // packets
  const fl = engine.flights;
  const maxDraw = 220;
  for (let i = 0; i < fl.length && i < maxDraw; i++){
    const f = fl[i];
    const e = geom.edges[f.edge];
    if (!e) continue;
    const u = clamp((now - f.t0) / Math.max(1, f.t1 - f.t0), 0, 1);
    const p = bez(e, u);
    const selHit = sel && sel.type === 'req' && sel.id === f.reqId;
    drawPacket(p.x, p.y, f.kind, selHit, bezTan(e, u));
  }

  // legend for paused handled via DOM
}

function drawBreakerGlyph(now){
  const e = geom.edges['workers>primary'];
  if (!e) return;
  const p = bez(e, .5);
  const b = engine.breaker;
  const col = b.state === 'closed' ? '#2ee6a8' : b.state === 'open' ? '#f4587a' : '#f5b04f';
  ctx.save();
  ctx.translate(p.x, p.y);
  const pulse = (b.state === 'open' && !reduceMotion.matches) ? 1 + .12 * Math.sin(now / 120) : 1;
  ctx.beginPath(); ctx.arc(0, 0, 10.5 * pulse, 0, 7);
  ctx.fillStyle = '#0b1220'; ctx.fill();
  ctx.lineWidth = 1.6; ctx.strokeStyle = col; ctx.stroke();
  ctx.strokeStyle = col; ctx.lineWidth = 2;
  ctx.beginPath();
  if (b.state === 'closed'){ ctx.moveTo(-6, 0); ctx.lineTo(6, 0); }
  else if (b.state === 'open'){ ctx.moveTo(-6, 0); ctx.lineTo(-2, 0); ctx.moveTo(2, -4); ctx.lineTo(6, -4); }
  else { ctx.setLineDash([2.5, 2.5]); ctx.moveTo(-6, 0); ctx.lineTo(6, 0); }
  ctx.stroke(); ctx.setLineDash([]);
  ctx.font = '700 7.5px ui-monospace,Menlo,monospace';
  ctx.fillStyle = col; ctx.textAlign = 'center';
  ctx.fillText(b.state.toUpperCase(), 0, 21);
  ctx.restore();
  geom.breakerHit = { x: p.x, y: p.y, r: 15 };
}

function healthColor(state){ return state === 'ok' ? '#2ee6a8' : state === 'warn' ? '#f5b04f' : state === 'bad' ? '#f4587a' : '#64748b'; }

function drawNode(n, now){
  const eng = engine;
  let health = 'idle', act = 0;
  for (const k in eng.edgeUse){
    if (k.startsWith(n.id + '>') || k.endsWith('>' + n.id)){
      act = Math.max(act, 1 - clamp((now - eng.edgeUse[k].t) / 900, 0, 1));
    }
  }
  // health per node
  if (n.id === 'primary') health = eng.primary.up ? 'ok' : 'bad';
  else if (n.id === 'queue') health = eng.queue.length >= .85 * eng.cfg.queueMax ? 'bad' : eng.queue.length >= .5 * eng.cfg.queueMax ? 'warn' : 'ok';
  else if (n.id === 'gateway') health = eng.gateway.rejectTimes.length > 2 ? 'warn' : 'ok';
  else if (n.id === 'workers'){ let st = 0; for (let i = 0; i < eng.workerCount; i++) if (eng.workers[i].stopped) st++; health = st ? 'warn' : 'ok'; }
  else if (n.id === 'replica'){ const pend = eng.repLog.length - eng.repApplied; health = (eng.replica.lag >= 1500 && pend > 0) ? 'warn' : 'ok'; }
  else if (n.id === 'dlq') health = eng.dlq.length ? 'bad' : 'idle';
  else if (n.id === 'retry') health = eng.retryQ.length > 4 ? 'warn' : eng.retryQ.length ? 'ok' : 'idle';
  else if (n.id === 'cache') health = 'ok';
  const hc = healthColor(health);
  const selNode = sel && sel.type === 'node' && sel.id === n.id;

  ctx.save();
  // glow when active
  if (act > 0 && !reduceMotion.matches){ ctx.shadowColor = hc; ctx.shadowBlur = 14 * act; }
  roundRect(n.x, n.y, n.w, n.h, 9);
  const grd = ctx.createLinearGradient(0, n.y, 0, n.y + n.h);
  grd.addColorStop(0, '#121c2e'); grd.addColorStop(1, '#0c1422');
  ctx.fillStyle = grd; ctx.fill();
  ctx.shadowBlur = 0;
  ctx.lineWidth = selNode ? 2 : 1.2;
  ctx.strokeStyle = selNode ? '#54d0f0' : hc + '55';
  ctx.stroke();
  // header band
  ctx.fillStyle = hc; ctx.globalAlpha = .9;
  ctx.fillRect(n.x + 8, n.y + 7, 5, 5);
  ctx.globalAlpha = 1;
  ctx.font = '700 9px ui-monospace,Menlo,monospace';
  ctx.fillStyle = '#8aa0bd'; ctx.textAlign = 'left';
  ctx.fillText(n.title, n.x + 17, n.y + 12.5);
  ctx.restore();

  const cx = n.x + 9, base = n.y + 27;
  ctx.font = '600 15px ui-monospace,Menlo,monospace';
  ctx.fillStyle = '#e2ecf9';
  ctx.textAlign = 'left';
  const sub = (txt, y, col) => { ctx.font = '500 9px ui-monospace,Menlo,monospace'; ctx.fillStyle = col || '#5a7089'; ctx.fillText(txt, cx, y); };
  const big = (txt, col) => { ctx.font = '700 15px ui-monospace,Menlo,monospace'; ctx.fillStyle = col || '#e2ecf9'; ctx.fillText(txt, cx, base + 3); };
  const bar = (frac, y, col) => {
    const bw = n.w - 18;
    ctx.fillStyle = '#1b2942'; ctx.fillRect(cx, y, bw, 4);
    ctx.fillStyle = col; ctx.fillRect(cx, y, bw * clamp(frac, 0, 1), 4);
  };

  if (n.id === 'clients'){
    big(String(eng.reqSeq), '#e2ecf9');
    sub(`${eng.trafficRate}/s demand`, base + 16);
    sub('requests sent', base + 27);
  } else if (n.id === 'gateway'){
    big(Math.floor(eng.gateway.tokens) + '/' + eng.cfg.tokenCap);
    bar(eng.gateway.tokens / eng.cfg.tokenCap, base + 8, '#54d0f0');
    sub(`tokens · refill ${eng.cfg.tokenRate}/s`, base + 22);
    sub(`429:${eng.gateway.rejectedRate}  shed:${eng.gateway.rejectedBp}`, base + 33, eng.gateway.rejectedRate + eng.gateway.rejectedBp > 0 ? '#f5b04f' : undefined);
  } else if (n.id === 'queue'){
    const d = eng.queue.length;
    big(String(d), d >= .85 * eng.cfg.queueMax ? '#f4587a' : d >= .5 * eng.cfg.queueMax ? '#f5b04f' : '#e2ecf9');
    bar(d / eng.cfg.queueMax, base + 8, hc);
    sub(`depth / ${eng.cfg.queueMax} max`, base + 22);
    sub(`peak ${eng.queueStats.peak} · out ${eng.queueStats.deq}`, base + 33);
  } else if (n.id === 'workers'){
    let busy = 0;
    for (let i = 0; i < eng.workerCount; i++) if (eng.workers[i].job) busy++;
    const cols = 6, sz = clamp((n.w - 24) / cols - 4, 8, 15);
    for (let i = 0; i < 12; i++){
      const wx = cx + (i % cols) * (sz + 4), wy = base - 6 + Math.floor(i / cols) * (sz + 4);
      const w = eng.workers[i];
      const inPool = i < eng.workerCount;
      ctx.beginPath(); roundRect(wx, wy, sz, sz, 3);
      if (!inPool){ ctx.strokeStyle = '#1b294266'; ctx.lineWidth = 1; ctx.stroke(); continue; }
      if (w.stopped){ ctx.fillStyle = '#3d1523'; ctx.fill(); ctx.strokeStyle = '#f4587a'; ctx.lineWidth = 1.2; ctx.stroke();
        ctx.beginPath(); ctx.moveTo(wx + 3, wy + 3); ctx.lineTo(wx + sz - 3, wy + sz - 3); ctx.moveTo(wx + sz - 3, wy + 3); ctx.lineTo(wx + 3, wy + sz - 3);
        ctx.strokeStyle = '#f4587a'; ctx.stroke(); }
      else if (w.job){
        const ph = reduceMotion.matches ? 0 : .15 * Math.sin(now / 130 + i);
        ctx.fillStyle = w.job.op === 'write' ? '#e879f9' : '#54d0f0'; ctx.globalAlpha = .75 + ph; ctx.fill(); ctx.globalAlpha = 1;
      } else { ctx.fillStyle = '#22314e'; ctx.fill(); }
    }
    sub(`${busy}/${eng.workerCount} busy · svc ~${eng.cfg.serviceMean}ms`, n.y + n.h - 20);
    sub(`${eng.workers.reduce((a, w) => a + w.done, 0)} jobs done`, n.y + n.h - 9);
  } else if (n.id === 'primary'){
    if (!eng.primary.up){
      ctx.save();
      roundRect(n.x, n.y, n.w, n.h, 9); ctx.clip();
      ctx.strokeStyle = '#f4587a22'; ctx.lineWidth = 5;
      for (let s = -n.h; s < n.w + n.h; s += 14){ ctx.beginPath(); ctx.moveTo(n.x + s, n.y); ctx.lineTo(n.x + s - n.h, n.y + n.h); ctx.stroke(); }
      ctx.restore();
    }
    big(eng.primary.up ? 'UP' : 'DOWN', eng.primary.up ? '#2ee6a8' : '#f4587a');
    ctx.font = '600 11px ui-monospace,Menlo,monospace'; ctx.fillStyle = '#8aa0bd';
    ctx.fillText('v' + eng.primary.version, cx + 46, base + 3);
    sub(`${eng.primary.commits} commits · ${eng.primary.records.size} keys`, base + 16);
    sub(`${eng.primary.dupes} dupes prevented`, base + 27, eng.primary.dupes ? '#2ee6a8' : undefined);
  } else if (n.id === 'replica'){
    const pend = eng.repLog.length - eng.repApplied;
    big((eng.replica.lag >= 1000 ? (eng.replica.lag / 1000) + 's' : eng.replica.lag + 'ms'), eng.replica.lag >= 1500 ? '#f5b04f' : '#e2ecf9');
    sub('replication lag', base + 16);
    sub(`v${eng.replica.appliedVersion}/${eng.primary.version} · ${pend} pending`, base + 27, pend ? '#f5b04f' : undefined);
  } else if (n.id === 'cache'){
    const tot = eng.cache.hits + eng.cache.misses;
    big(tot ? Math.round(100 * eng.cache.hits / tot) + '%' : '–');
    sub(`hit rate · ${eng.cache.map.size} keys`, base + 16);
    sub(`${eng.cache.hits} hit · ${eng.cache.misses} miss · ${eng.cache.expired} exp`, base + 27);
  } else if (n.id === 'retry'){
    big(String(eng.retryQ.length), eng.retryQ.length ? '#f5b04f' : '#e2ecf9');
    let next = null;
    for (const e of eng.retryQ) if (next == null || e.at < next) next = e.at;
    sub('pending retries', base + 16);
    sub(next != null ? `next in ${Math.max(0, Math.round(next - now))}ms` : 'idle', base + 27);
  } else if (n.id === 'dlq'){
    const pulse = eng.dlq.length && !reduceMotion.matches ? .5 + .5 * Math.abs(Math.sin(now / 400)) : 1;
    big(String(eng.dlq.length), eng.dlq.length ? `rgba(255,91,126,${pulse})` : '#e2ecf9');
    sub('dead letters', base + 16);
    sub(eng.dlq.length ? 'replayable ↺' : 'empty', base + 27, eng.dlq.length ? '#ff8aa5' : undefined);
  }
}

function roundRect(x, y, w, h, r){
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function drawPacket(x, y, kind, selected, tan){
  const col = KIND_COLOR[kind] || '#54d0f0';
  ctx.save();
  ctx.translate(x, y);
  if (!reduceMotion.matches && engine.flights.length < 120){ ctx.shadowColor = col; ctx.shadowBlur = 7; }
  ctx.fillStyle = col; ctx.strokeStyle = col; ctx.lineWidth = 1.8;
  switch (kind){
    case 'read': ctx.beginPath(); ctx.arc(0, 0, 4.4, 0, 7); ctx.fill(); break;
    case 'write': roundRectP(-4, -4, 8, 8, 2); ctx.fill(); break;
    case 'retry': ctx.rotate(Math.PI / 4); roundRectP(-4, -4, 8, 8, 1.5); ctx.fill(); break;
    case 'hit': ctx.beginPath(); ctx.arc(0, 0, 2.4, 0, 7); ctx.fill(); ctx.beginPath(); ctx.arc(0, 0, 5.5, 0, 7); ctx.stroke(); break;
    case 'stale': ctx.beginPath(); ctx.moveTo(0, 5); ctx.lineTo(-4.6, -3.4); ctx.lineTo(4.6, -3.4); ctx.closePath(); ctx.stroke(); break;
    case 'fail': ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(-4.6, 3.6); ctx.lineTo(4.6, 3.6); ctx.closePath(); ctx.fill(); break;
    case 'dead': ctx.lineWidth = 2.4; ctx.beginPath(); ctx.moveTo(-4, -4); ctx.lineTo(4, 4); ctx.moveTo(4, -4); ctx.lineTo(-4, 4); ctx.stroke(); break;
    case 'ok': ctx.beginPath(); ctx.arc(0, 0, 3.4, 0, 7); ctx.fill();
      if (tan){ ctx.globalAlpha = .5; ctx.beginPath(); ctx.moveTo(-tan.x * 5, -tan.y * 5); ctx.lineTo(-tan.x * 10, -tan.y * 10); ctx.stroke(); ctx.globalAlpha = 1; } break;
    case 'rep': if (tan){ ctx.rotate(Math.atan2(tan.y, tan.x)); } roundRectP(-6, -2.4, 12, 4.8, 2.4); ctx.fill(); break;
    case 'inv': roundRectP(-4, -4, 8, 8, 2); ctx.stroke(); break;
    case 'fill': ctx.beginPath(); ctx.arc(0, 0, 4.2, 0, 7); ctx.stroke(); ctx.beginPath(); ctx.arc(0, 0, 1.6, 0, 7); ctx.fill(); break;
    default: ctx.beginPath(); ctx.arc(0, 0, 4, 0, 7); ctx.fill();
  }
  ctx.shadowBlur = 0;
  if (selected){ ctx.beginPath(); ctx.arc(0, 0, 9, 0, 7); ctx.strokeStyle = '#ffffffcc'; ctx.lineWidth = 1.4; ctx.stroke(); }
  ctx.restore();
}
function roundRectP(x, y, w, h, r){
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

/* ---------- charts ---------- */
function drawSpark(canvas, data, color, opts = {}){
  const w = canvas.clientWidth, h = canvas.clientHeight;
  if (!w || !h) return;
  const dpr = Math.min(devicePixelRatio || 1, 2.5);
  if (canvas.width !== Math.round(w * dpr)){ canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr); }
  const g = canvas.getContext('2d');
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  g.clearRect(0, 0, w, h);
  g.strokeStyle = '#1b294288'; g.lineWidth = 1;
  for (let i = 1; i <= 2; i++){ g.beginPath(); g.moveTo(0, h * i / 3); g.lineTo(w, h * i / 3); g.stroke(); }
  const n = data.length;
  if (!n) return;
  let max = opts.fixedMax || 0;
  if (!opts.fixedMax){ for (const v of data) if (v > max) max = v; max = Math.max(max * 1.15, opts.minMax || 1); }
  if (opts.threshold != null){
    const ty = h - 3 - (h - 8) * clamp(opts.threshold / max, 0, 1);
    g.strokeStyle = '#f4587a44'; g.setLineDash([3, 3]);
    g.beginPath(); g.moveTo(0, ty); g.lineTo(w, ty); g.stroke(); g.setLineDash([]);
  }
  const step = w / 240;
  const xAt = i => w - (n - 1 - i) * step;
  const yAt = v => h - 3 - (h - 8) * clamp(v / max, 0, 1);
  g.beginPath();
  for (let i = 0; i < n; i++){ const x = xAt(i), y = yAt(data[i]); i ? g.lineTo(x, y) : g.moveTo(x, y); }
  g.strokeStyle = color; g.lineWidth = 1.6; g.lineJoin = 'round'; g.stroke();
  g.lineTo(xAt(n - 1), h); g.lineTo(xAt(0), h); g.closePath();
  const grad = g.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, color + '33'); grad.addColorStop(1, color + '00');
  g.fillStyle = grad; g.fill();
  g.beginPath(); g.arc(xAt(n - 1), yAt(data[n - 1]), 2.4, 0, 7);
  g.fillStyle = color; g.fill();
}

/* ---------- log ---------- */
const logEl = $('log');
let uiLogSeq = 0, uiResetToken = engine.resetToken, lastLogNode = null, lastLogEntry = null;
function flushLog(){
  if (uiResetToken !== engine.resetToken){
    uiResetToken = engine.resetToken; uiLogSeq = 0; logEl.innerHTML = ''; lastLogNode = null; lastLogEntry = null;
  }
  const L = engine.log;
  if (lastLogEntry && lastLogNode && lastLogEntry.n > 1 && lastLogNode.dataset.n !== String(lastLogEntry.n)){
    lastLogNode.dataset.n = String(lastLogEntry.n);
    const nEl = lastLogNode.querySelector('.n');
    if (nEl) nEl.textContent = ' ×' + lastLogEntry.n;
  }
  let start = L.length;
  while (start > 0 && L[start - 1].seq > uiLogSeq) start--;
  if (start === L.length) return;
  const nearBottom = logEl.scrollHeight - logEl.scrollTop - logEl.clientHeight < 40;
  const frag = document.createDocumentFragment();
  for (let i = start; i < L.length; i++){
    const e = L[i];
    const d = document.createElement('div');
    d.className = 'lr ' + e.level;
    d.dataset.n = String(e.n);
    let msg = esc(e.msg);
    if (e.reqId) msg = msg.replace(esc(e.reqId), `<span class="rq" data-rq="${esc(e.reqId)}">${esc(e.reqId)}</span>`);
    d.innerHTML = `<span class="t">${fmtT(e.t)}</span> <span class="c">${esc(e.comp)}</span> <span class="m">${msg}</span><span class="n">${e.n > 1 ? ' ×' + e.n : ''}</span>`;
    frag.appendChild(d);
    lastLogNode = d; lastLogEntry = e;
  }
  uiLogSeq = L[L.length - 1].seq;
  logEl.appendChild(frag);
  while (logEl.childElementCount > 280) logEl.removeChild(logEl.firstElementChild);
  if (nearBottom) logEl.scrollTop = logEl.scrollHeight;
  $('logCount').textContent = engine.logSeq + ' events';
}
logEl.addEventListener('click', e => {
  const rq = e.target.closest('[data-rq]');
  if (rq) selectReq(rq.dataset.rq);
});

/* ---------- tabs & panels ---------- */
const panels = { insp: $('panelInspector'), dlq: $('panelDlq'), diag: $('panelDiag') };
const tabBtns = { insp: $('tabInsp'), dlq: $('tabDlq'), diag: $('tabDiag') };
let curTab = 'insp';
function setTab(t){
  curTab = t;
  for (const k in panels){ panels[k].classList.toggle('on', k === t); tabBtns[k].classList.toggle('on', k === t); }
  if (t === 'dlq') renderDlq(true);
  if (t === 'diag') renderDiag();
  if (t === 'insp') renderInspector(true);
}
tabBtns.insp.addEventListener('click', () => setTab('insp'));
tabBtns.dlq.addEventListener('click', () => setTab('dlq'));
tabBtns.diag.addEventListener('click', () => setTab('diag'));

