/* ---------- inspector ---------- */
function stateChip(s){ return `<span class="statechip st-${esc(s)}">${esc(s)}</span>`; }

function renderInspector(force){
  const p = panels.insp;
  if (!p.classList.contains('on')) return;
  if (!force && p.contains(document.activeElement) && document.activeElement !== p) return;
  if (!sel){
    const sc = SCENARIOS[engine.scenario];
    const s = engine.snapshot();
    p.innerHTML = `
      <h3>System overview</h3>
      <p class="mut" style="margin:4px 0 10px">${sc.blurb}</p>
      <div class="kv">
        <span>state</span><b>${esc(s.systemState.toUpperCase())}</b>
        <span>in-flight requests</span><b>${s.requests.active}</b>
        <span>circuit breaker</span><b>${esc(s.circuitBreaker.state)}</b>
        <span>retry backlog</span><b>${s.retryScheduler.pending.length}</b>
        <span>replica pending</span><b>${s.replica.pendingOps}</b>
        <span>stale reads served</span><b>${s.replica.staleReads}</b>
        <span>avg latency (5s)</span><b>${Math.round(s.metrics.avgLatencyMs)}ms</b>
      </div>
      <p class="mut">Click a packet in flight, any component, the breaker glyph on the workers→primary link, or a request id in the log to inspect it.</p>`;
    return;
  }
  if (sel.type === 'req'){
    const r = engine.requests.get(sel.id);
    if (!r){ p.innerHTML = `<h3>Request</h3><p class="mut">${esc(sel.id)} has been pruned from history.</p>`; return; }
    const rows = r.history.map(h =>
      `<li class="evt-${esc(h.code)}"><span class="tt">${fmtT(h.t)}</span>${esc(h.msg)}</li>`).join('');
    p.innerHTML = `
      <h3>Request ${esc(r.id)} ${stateChip(r.state)}</h3>
      <div class="kv">
        <span>operation</span><b>${esc(r.op)} ${esc(r.key)}</b>
        <span>tenant</span><b>${esc(r.tenant)}</b>
        ${r.idemKey ? `<span>idempotency key</span><b>${esc(r.idemKey)}</b>` : ''}
        ${r.value != null ? `<span>value</span><b>${esc(r.value)}</b>` : ''}
        <span>attempts</span><b>${r.attempts}/${engine.cfg.maxAttempts}${r.deferrals ? ` (+${r.deferrals} deferred)` : ''}</b>
        <span>created</span><b>${fmtT(r.createdAt)}</b>
        ${r.latency != null ? `<span>latency</span><b>${r.latency}ms</b>` : ''}
        ${r.result ? `<span>served via</span><b>${esc(r.result.via)}${r.result.stale ? ' · STALE' : ''}${r.result.dedup ? ' · dedup' : ''}</b>` : ''}
        ${r.poison ? `<span>flag</span><b style="color:var(--rose)">POISON</b>` : ''}
      </div>
      ${r.state === 'dead-lettered' ? `<button class="btn" data-act="repair-replay" data-id="${esc(r.id)}">Repair &amp; replay</button>` : ''}
      <h3 style="margin-top:12px">Lifecycle</h3>
      <ul class="tl">${rows}</ul>`;
    return;
  }
  if (sel.type === 'breaker'){
    const b = engine.breaker;
    p.innerHTML = `
      <h3>Circuit breaker ${stateChip(b.state)}</h3>
      <div class="kv">
        <span>consecutive failures</span><b>${b.fails}/${engine.cfg.breakerThreshold}</b>
        <span>opened at</span><b>${b.opens ? fmtT(b.openedAt) : '–'}</b>
        <span>times opened</span><b>${b.opens}</b>
        <span>cooldown</span><b>${engine.cfg.breakerCooldown}ms</b>
      </div>
      <p class="mut">Protects the primary from write storms. After ${engine.cfg.breakerThreshold} consecutive infrastructure failures it opens and writes fail fast into the retry scheduler. After ${engine.cfg.breakerCooldown}ms it half-opens and one probe write decides: success closes it, failure re-opens it. Reads bypass it entirely — they go to the replica.</p>`;
    return;
  }
  if (sel.type === 'record'){
    const store = sel.store === 'replica' ? engine.replica.records : engine.primary.records;
    const rec = store.get(sel.key);
    if (!rec){ p.innerHTML = `<h3>Record</h3><p class="mut">${esc(sel.key)} not present in ${esc(sel.store)}.</p>`; return; }
    const other = sel.store === 'replica' ? engine.primary.records.get(sel.key) : engine.replica.records.get(sel.key);
    p.innerHTML = `
      <h3>Record ${esc(sel.key)} <span class="mut">(${esc(sel.store)})</span></h3>
      <div class="kv">
        <span>value</span><b>${esc(rec.value)}</b>
        <span>version</span><b>v${rec.version}</b>
        <span>committed at</span><b>${fmtT(rec.at)}</b>
        ${rec.by ? `<span>written by</span><b><span class="linkish" data-rq="${esc(rec.by)}">${esc(rec.by)}</span></b>` : ''}
        ${rec.idemKey ? `<span>idempotency key</span><b>${esc(rec.idemKey)}</b>` : ''}
        <span>${sel.store === 'replica' ? 'primary' : 'replica'} version</span><b>${other ? 'v' + other.version : 'absent'}</b>
      </div>
      <p class="mut linkish" data-act="select-node" data-id="${sel.store === 'replica' ? 'replica' : 'primary'}">← back to ${esc(sel.store)}</p>`;
    return;
  }
  // node
  const id = sel.id, s = engine;
  let html = '';
  const recTable = (map, store) => {
    const rows = [...map.values()].sort((a, b) => a.key < b.key ? -1 : 1).slice(0, 24)
      .map(r => `<tr class="clickable" data-act="select-record" data-store="${store}" data-key="${esc(r.key)}"><td>${esc(r.key)}</td><td>${esc(r.value)}</td><td>v${r.version}</td><td>${fmtT(r.at)}</td></tr>`).join('');
    return `<table class="recs"><tr><th>key</th><th>value</th><th>ver</th><th>committed</th></tr>${rows || '<tr><td colspan="4" class="mut">empty</td></tr>'}</table>`;
  };
  if (id === 'primary'){
    html = `<h3>Primary database ${stateChip(s.primary.up ? 'completed' : 'rejected')}</h3>
      <div class="kv"><span>status</span><b>${s.primary.up ? 'UP' : 'DOWN'}</b>
      <span>commits</span><b>${s.primary.commits}</b><span>version</span><b>v${s.primary.version}</b>
      <span>duplicates prevented</span><b>${s.primary.dupes}</b><span>idempotency keys</span><b>${s.primary.idem.size}</b></div>
      <button class="btn ${s.primary.up ? 'danger' : 'primary'}" data-act="${s.primary.up ? 'fail-db' : 'recover-db'}">${s.primary.up ? 'Fail primary' : 'Recover primary'}</button>
      <h3 style="margin-top:12px">Stored records <span class="mut">(click to inspect)</span></h3>${recTable(s.primary.records, 'primary')}`;
  } else if (id === 'replica'){
    const pend = s.repLog.length - s.repApplied;
    html = `<h3>Read replica</h3>
      <div class="kv"><span>lag</span><b>${s.replica.lag}ms</b><span>applied</span><b>v${s.replica.appliedVersion}/${s.primary.version}</b>
      <span>pending ops</span><b>${pend}</b><span>stale reads served</span><b>${s.replica.staleReads}</b></div>
      <div class="sliderwrap" style="margin:6px 0">lag <input type="range" min="0" max="8000" step="250" value="${s.replica.lag}" data-act="lag-slider" aria-label="Replica lag"> <b>${s.replica.lag}ms</b></div>
      <h3 style="margin-top:12px">Replica records</h3>${recTable(s.replica.records, 'replica')}`;
  } else if (id === 'cache'){
    const rows = [...s.cache.map.entries()].slice(0, 20).map(([k, e]) =>
      `<tr><td>${esc(k)}</td><td>${esc(e.value)}</td><td>v${e.version}</td><td>${Math.max(0, Math.round(e.expiresAt - s.now))}ms</td><td>${e.hits}</td></tr>`).join('');
    html = `<h3>TTL cache</h3>
      <div class="kv"><span>entries</span><b>${s.cache.map.size}</b><span>hits / misses</span><b>${s.cache.hits} / ${s.cache.misses}</b>
      <span>expired evictions</span><b>${s.cache.expired}</b><span>invalidations</span><b>${s.cache.invalidations}</b><span>TTL</span><b>${s.cfg.cacheTTL}ms</b></div>
      <button class="btn" data-act="clear-cache">Flush cache</button>
      <h3 style="margin-top:12px">Live entries</h3>
      <table class="recs"><tr><th>key</th><th>value</th><th>ver</th><th>ttl left</th><th>hits</th></tr>${rows || '<tr><td colspan="5" class="mut">empty</td></tr>'}</table>`;
  } else if (id === 'workers'){
    const rows = s.workers.slice(0, s.workerCount).map(w => `
      <tr><td>W${w.id}</td><td>${w.stopped ? '<span style="color:var(--rose)">stopped</span>' : w.job ? `busy · <span class="linkish" data-rq="${esc(w.job.id)}">${esc(w.job.id)}</span>` : 'idle'}</td>
      <td>${w.done}</td>
      <td>${w.stopped ? `<button class="btn" data-act="restore-worker" data-w="${w.id}">restore</button>` : `<button class="btn" data-act="stop-worker" data-w="${w.id}">stop</button>`}</td></tr>`).join('');
    html = `<h3>Worker pool</h3>
      <div class="kv"><span>pool size</span><b>${s.workerCount}</b><span>service time</span><b>~${s.cfg.serviceMean}ms ±${Math.round(s.cfg.serviceJitter * 100)}%</b></div>
      <p class="mut">At-least-once processing: a stopped worker's in-flight job is requeued; idempotency keys make redelivery safe.</p>
      <table class="recs"><tr><th>id</th><th>state</th><th>done</th><th></th></tr>${rows}</table>`;
  } else if (id === 'queue'){
    const rows = s.queue.slice(0, 12).map((r, i) => `<tr class="clickable" data-act="select-req" data-id="${esc(r.id)}"><td>${i + 1}</td><td>${esc(r.id)}</td><td>${esc(r.op)} ${esc(r.key)}</td><td>${r.attempts ? 'retry #' + r.attempts : 'fresh'}</td></tr>`).join('');
    html = `<h3>Work queue</h3>
      <div class="kv"><span>depth</span><b>${s.queue.length}/${s.cfg.queueMax}</b><span>peak</span><b>${s.queueStats.peak}</b>
      <span>enqueued</span><b>${s.queueStats.enq}</b><span>dispatched</span><b>${s.queueStats.deq}</b></div>
      <p class="mut">FIFO with a hard bound — when full, the gateway sheds new work (backpressure) rather than growing without limit.</p>
      <table class="recs"><tr><th>#</th><th>req</th><th>op</th><th>attempt</th></tr>${rows || '<tr><td colspan="4" class="mut">empty</td></tr>'}</table>`;
  } else if (id === 'gateway'){
    html = `<h3>API gateway</h3>
      <div class="kv"><span>tokens</span><b>${Math.floor(s.gateway.tokens)}/${s.cfg.tokenCap}</b>
      <span>refill</span><b>${s.cfg.tokenRate}/s</b><span>accepted</span><b>${s.gateway.accepted}</b>
      <span>rate-limited (429)</span><b>${s.gateway.rejectedRate}</b><span>shed / backpressure</span><b>${s.gateway.rejectedBp}</b></div>
      <div class="sliderwrap" style="margin:6px 0">capacity <input type="range" min="2" max="40" step="1" value="${s.cfg.tokenRate}" data-act="token-slider" aria-label="Gateway token refill rate"> <b>${s.cfg.tokenRate}/s</b></div>
      <p class="mut">Token bucket: each admitted request consumes one token. Lower the refill rate to throttle intake and watch 429s appear.</p>`;
  } else if (id === 'retry'){
    const rows = s.retryQ.slice().sort((a, b) => a.at - b.at).slice(0, 12).map(e =>
      `<tr class="clickable" data-act="select-req" data-id="${esc(e.reqId)}"><td>${esc(e.reqId)}</td><td>#${e.attempt}</td><td>${fmtT(e.at)}</td><td>${e.deferred ? 'circuit' : 'backoff'}</td></tr>`).join('');
    html = `<h3>Retry scheduler</h3>
      <div class="kv"><span>pending</span><b>${s.retryQ.length}</b><span>scheduled total</span><b>${s.retryStats.scheduled}</b><span>fired</span><b>${s.retryStats.fired}</b>
      <span>policy</span><b>${s.cfg.retryBase}ms × ${s.cfg.retryFactor}^n</b></div>
      <table class="recs"><tr><th>req</th><th>attempt</th><th>due at</th><th>cause</th></tr>${rows || '<tr><td colspan="4" class="mut">empty</td></tr>'}</table>`;
  } else if (id === 'dlq'){
    html = `<h3>Dead-letter queue</h3><p class="mut">Work that exhausted all ${s.cfg.maxAttempts} attempts. See the <span class="linkish" data-act="open-dlq">Dead letters tab</span> to repair &amp; replay items.</p>
