  }
  p.innerHTML = html;
}

/* ---------- DLQ panel ---------- */
let dlqRenderedStamp = -1;
function renderDlq(force){
  if (!panels.dlq.classList.contains('on')) return;
  if (!force && dlqRenderedStamp === engine.dlqStamp) return;
  dlqRenderedStamp = engine.dlqStamp;
  const items = engine.dlq.map(d => {
    const r = engine.requests.get(d.reqId);
    return `<div class="dlqitem">
      <div class="row"><b class="linkish" data-rq="${esc(d.reqId)}">${esc(d.reqId)}</b><span class="mut">${esc(d.key)} · ${d.attempts} attempts · ${fmtT(d.at)}</span></div>
      <div class="why">${esc(d.reason)}${r && r.poison ? ' · still poisoned' : ''}</div>
      <div class="row">
        <button class="btn primary" data-act="repair-replay" data-id="${esc(d.reqId)}">Repair &amp; replay</button>
        <button class="btn" data-act="replay" data-id="${esc(d.reqId)}" title="Replay without clearing the poison flag — it will fail again">Replay as-is</button>
      </div></div>`;
  }).join('');
  panels.dlq.innerHTML = `<h3>Dead letters (${engine.dlq.length})</h3>` +
    (items || '<p class="mut">No dead letters. Run the “Poison msg” scenario to create one, then repair &amp; replay it here.</p>');
}

/* ---------- diagnostics panel ---------- */
let lastSelfTest = null;
function renderDiag(){
  const p = panels.diag;
  const r = lastSelfTest;
  const rows = r ? r.tests.map(t =>
    `<div class="testrow ${t.pass ? 'pass' : 'fail'}"><span class="tick">${t.pass ? '✓' : '✗'}</span><span>${esc(t.name)}<br><span class="det">${esc(t.detail)}</span></span></div>`).join('') : '<p class="mut">Not run yet.</p>';
  p.innerHTML = `
    <h3>Self-test ${r ? (r.passed ? '<span style="color:var(--teal)">— all passing</span>' : '<span style="color:var(--rose)">— FAILURES</span>') : ''}</h3>
    <button class="btn primary" data-act="run-selftest">Run self-test</button>
    <div style="margin-top:8px">${rows}</div>
    <h3 style="margin-top:14px">Diagnostic API</h3>
    <p class="mut" style="line-height:1.9">
      <code class="api">__DSP__.reset(seed)</code> reset current scenario with integer seed<br>
      <code class="api">__DSP__.setScenario(name)</code> healthy · flash-crowd · database-outage · poison-message · stale-replica<br>
      <code class="api">__DSP__.step(ms)</code> advance simulated time deterministically<br>
      <code class="api">__DSP__.sendRequest({op,key,idemKey,value,poison})</code> → request id<br>
      <code class="api">__DSP__.snapshot()</code> JSON-safe state summary<br>
      <code class="api">__DSP__.runSelfTest()</code> → { passed, tests }
    </p>`;
  const dot = $('diagDot');
  dot.className = 'dot' + (r ? (r.passed ? ' ok' : ' bad') : '');
}
function doSelfTest(){
  lastSelfTest = runSelfTests();
  renderDiag();
  return lastSelfTest;
}

/* ---------- shared click delegation ---------- */
document.getElementById('side').addEventListener('click', e => {
  const rq = e.target.closest('[data-rq]');
  if (rq){ selectReq(rq.dataset.rq); return; }
  const el = e.target.closest('[data-act]');
  if (!el) return;
  const act = el.dataset.act;
  if (act === 'repair-replay') engine.replayDlq(el.dataset.id, true);
  else if (act === 'replay') engine.replayDlq(el.dataset.id, false);
