  else if (act === 'fail-db') engine.setPrimaryUp(false);
  else if (act === 'recover-db') engine.setPrimaryUp(true);
  else if (act === 'clear-cache'){ engine.cache.map.clear(); engine.addLog('info', 'cache', 'cache flushed by operator', { code: 'flush' }); }
  else if (act === 'open-dlq') setTab('dlq');
  else if (act === 'run-selftest') doSelfTest();
  if (curTab === 'insp') renderInspector(true);
  if (curTab === 'dlq') renderDlq(true);
});
