+<script>
+"use strict";
+/* =====================================================================================
+   Cursor Grok 4.6 — Distributed Systems Playground
+   One deterministic discrete-time simulation drives packets, metrics, logs, and state.
+   Rendering never feeds back into the model. Wall clock only paces the animation loop.
