node << 'END'
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const http = require('http');
const { pathToFileURL } = require('url');

const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const FILE = pathToFileURL(path.resolve('index.html')).href;
const PORT = 9333;
const USER = '/tmp/dsp-chrome-val-' + Date.now();

const chrome = spawn(CHROME, [
  '--headless=new',
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check',
  '--disable-extensions',
  '--remote-debugging-port=' + PORT,
  '--user-data-dir=' + USER,
  FILE
], { stdio: ['ignore', 'pipe', 'pipe'] });

let stderr = '';
chrome.stderr.on('data', d => { stderr += d.toString(); });

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function waitPort(tries = 40) {
  for (let i = 0; i < tries; i++) {
    try {
      const res = await fetch('http://127.0.0.1:' + PORT + '/json/list');
      if (res.ok) return await res.json();
    } catch {}
    await sleep(150);
  }
  throw new Error('CDP not ready. stderr=' + stderr.slice(-800));
}

function cdp(ws, method, params = {}, sessionId) {
  return new Promise((resolve, reject) => {
    const id = cdp._n = (cdp._n || 0) + 1;
    const t = setTimeout(() => { ws.removeEventListener('message', onmsg); reject(new Error('timeout ' + method)); }, 20000);
    function onmsg(ev) {
      const msg = JSON.parse(ev.data);
      if (msg.id === id) {
        clearTimeout(t);
        ws.removeEventListener('message', onmsg);
        if (msg.error) reject(new Error(method + ': ' + JSON.stringify(msg.error)));
        else resolve(msg.result);
      }
    }
    ws.addEventListener('message', onmsg);
    const payload = { id, method, params };
    if (sessionId) payload.sessionId = sessionId;
    ws.send(JSON.stringify(payload));
  });
}

(async () => {
  try {
    const list = await waitPort();
    const page = list.find(p => p.type === 'page') || list[0];
    if (!page) throw new Error('no page: ' + JSON.stringify(list));
    const ws = new WebSocket(page.webSocketDebuggerUrl);
    await new Promise((res, rej) => { ws.addEventListener('open', res); ws.addEventListener('error', rej); });

    await cdp(ws, 'Runtime.enable');
    await cdp(ws, 'Page.enable');
    await sleep(400);

    async function evalExpr(expr) {
      const r = await cdp(ws, 'Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
      if (r.exceptionDetails) throw new Error(expr + ' => ' + JSON.stringify(r.exceptionDetails.exception || r.exceptionDetails));
      return r.result.value;
    }

    const cons = [];
    ws.addEventListener('message', ev => {
      const msg = JSON.parse(ev.data);
      if (msg.method === 'Runtime.consoleAPICalled') {
        cons.push(msg.params.type + ': ' + (msg.params.args || []).map(a => a.value ?? a.description).join(' '));
      }
      if (msg.method === 'Runtime.exceptionThrown') {
        cons.push('EXCEPTION: ' + (msg.params.exceptionDetails?.exception?.description || JSON.stringify(msg.params)));
      }
    });

    const title = await evalExpr('document.title');
    const h1 = await evalExpr('document.querySelector("h1").textContent');
    const dsp = await evalExpr('typeof window.__DSP__ === "object" && typeof __DSP__.snapshot === "function"');
    const snap0 = await evalExpr('JSON.parse(JSON.stringify(__DSP__.snapshot()))');

    console.log('title:', title);
    console.log('h1:', h1);
    console.log('__DSP__:', dsp);
    console.log('initial snapshot time/scenario/state:', snap0.time, snap0.scenario, snap0.systemState);

    const self = await evalExpr('JSON.parse(JSON.stringify(__DSP__.runSelfTest()))');
    console.log('in-page self-test passed:', self.passed, self.tests.map(t => (t.pass ? '✓' : '✗') + t.name).join(' | '));

    // pause / step
    await evalExpr('__DSP__.reset(1337); document.getElementById("btnPlay").click();');
    const tPause = await evalExpr('(function(){ const t=__DSP__.snapshot().time; return { paused: __DSP__.snapshot().paused, t }; })()');
    await sleep(250);
    const tHeld = await evalExpr('__DSP__.snapshot().time');
    await evalExpr('__DSP__.step(500)');
    const tStep = await evalExpr('__DSP__.snapshot().time');
    console.log('pause/step:', { paused: tPause.paused, held: tHeld, afterStep: tStep });

    // deterministic reset
    await evalExpr('__DSP__.reset(42); __DSP__.step(2000); window._a = JSON.stringify(__DSP__.snapshot()); __DSP__.reset(42); __DSP__.step(2000); window._b = JSON.stringify(__DSP__.snapshot());');
    const det = await evalExpr('window._a === window._b');
    console.log('deterministic reset:', det);

    // scenarios
    const scenarios = ['healthy','flash-crowd','database-outage','poison-message','stale-replica'];
    for (const sc of scenarios) {
      const r = await evalExpr(`(function(){ __DSP__.setScenario(${JSON.stringify(sc)}); __DSP__.step(800); const s=__DSP__.snapshot(); return { scenario:s.scenario, time:s.time, workers:s.workers.length }; })()`);
      console.log('scenario', sc, r);
    }

    // duplicate protection
    const dup = await evalExpr(`(function(){
      __DSP__.setScenario('healthy'); __DSP__.reset(9);
      // freeze traffic
      const s0 = __DSP__.snapshot();
      document.getElementById('traffic').value = 0; document.getElementById('traffic').dispatchEvent(new Event('input'));
      const id1 = __DSP__.sendRequest({ op:'write', key:'order:5', idemKey:'dup-ui', value:'vX' });
      const id2 = __DSP__.sendRequest({ op:'write', key:'order:5', idemKey:'dup-ui', value:'vX' });
      __DSP__.step(9000);
      const s = __DSP__.snapshot();
      return { id1, id2, commits:s.primary.commits, dupes:s.primary.duplicatesPrevented };
    })()`);
    console.log('dupes:', dup);

    // db fail / recover
    const db = await evalExpr(`(function(){
      __DSP__.setScenario('healthy'); __DSP__.reset(11);
      document.getElementById('traffic').value = 0; document.getElementById('traffic').dispatchEvent(new Event('input'));
      document.getElementById('btnDb').click();
      const down = __DSP__.snapshot().primary.up;
      const id = __DSP__.sendRequest({ op:'write', key:'cart:4', idemKey:'down-ui', value:'vD' });
      __DSP__.step(3000);
      const mid = __DSP__.snapshot();
      document.getElementById('btnDb').click();
      __DSP__.step(15000);
      const end = __DSP__.snapshot();
      return { down: !down, commitsWhileDown: mid.primary.commits, commitsAfter: end.primary.commits, breaker: end.circuitBreaker.state, primaryUp: end.primary.up };
    })()`);
    console.log('db fail/recover:', db);

    // poison + replay
    const poison = await evalExpr(`(function(){
      __DSP__.setScenario('poison-message'); __DSP__.reset(13);
      document.getElementById('traffic').value = 0; document.getElementById('traffic').dispatchEvent(new Event('input'));
      const id = __DSP__.sendRequest({ op:'write', key:'invoice:13', idemKey:'poison-ui', value:'vP', poison:true });
      __DSP__.step(25000);
      const mid = __DSP__.snapshot();
      const n = mid.deadLetterQueue.length;
      // repair replay via API path used by UI
      const btn = document.querySelector('[data-act="repair-replay"]');
      if (btn) btn.click();
      else {
        // fallback: call replay through inspector after opening dlq
      }
      // always call sim via send? we need replay. Use internal by clicking DLQ tab then button.
      document.getElementById('tabDlq').click();
      const b2 = document.querySelector('[data-act="repair-replay"]');
      if (b2) b2.click();
      __DSP__.step(8000);
      const end = __DSP__.snapshot();
      return { id, dlqMid: n, dlqEnd: end.deadLetterQueue.length, commits: end.primary.commits, keys: end.primary.records.map(r=>r.key) };
    })()`);
    console.log('poison/replay:', poison);

    // responsive
    await cdp(ws, 'Emulation.setDeviceMetricsOverride', { width: 420, height: 800, deviceScaleFactor: 2, mobile: true });
    await sleep(200);
    const narrow = await evalExpr(`(function(){
      const main = document.querySelector('main');
      const cs = getComputedStyle(main);
      return { cols: cs.gridTemplateColumns, boardH: document.getElementById('board').getBoundingClientRect().height, w: innerWidth };
    })()`);
    console.log('narrow layout:', narrow);

    await cdp(ws, 'Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 2, mobile: false });
    await sleep(200);
    const wide = await evalExpr(`(function(){
      const cs = getComputedStyle(document.querySelector('main'));
      return { cols: cs.gridTemplateColumns, w: innerWidth, canvas: document.getElementById('topo').width };
    })()`);
    console.log('wide layout:', wide);

    const errors = cons.filter(c => /error|exception|fail/i.test(c) && !/self-test|FAILURES/.test(c));
    console.log('console:', cons.slice(0, 20));
    console.log('console errors:', errors);

    const pass =
      title === 'Cursor Grok 4.6' &&
      h1 === 'Cursor Grok 4.6' &&
      dsp && self.passed &&
      tPause.paused === true && tHeld === tPause.t && tStep > tHeld &&
      det &&
      dup.commits === 1 && dup.dupes >= 1 &&
      db.down && db.commitsWhileDown === 0 && db.primaryUp &&
      poison.dlqMid >= 1 && poison.dlqEnd === 0 && poison.commits >= 1 &&
      narrow.w <= 500 && wide.canvas > 0 &&
      errors.length === 0;

    console.log(pass ? '\nBROWSER VALIDATION PASS' : '\nBROWSER VALIDATION FAIL');
    ws.close();
    chrome.kill('SIGKILL');
    process.exit(pass ? 0 : 1);
  } catch (err) {
    console.error('VALIDATION ERROR', err);
    chrome.kill('SIGKILL');
    process.exit(1);
  }
})();
END

