const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const script = html.match(/<script>\s*"use strict";([\s\S]*?)\nconst \$ = id =>/)[1];
const { Sim } = new Function(script + '\nreturn { Sim, runSelfTests, frameAdvance };')();

function check(name, pass, detail) {
  console.log((pass ? 'PASS' : 'FAIL') + '  ' + name + ' — ' + detail);
  return pass;
}

let all = true;

// flash crowd: rate limits appear
{
  const e = new Sim(23, 'flash-crowd');
  e.step(9000);
  const s = e.snapshot();
  all &= check('flash crowd rate-limits', s.gateway.rejectedRateLimit > 0 || s.queue.peak > 10,
    `429s=${s.gateway.rejectedRateLimit} peakQ=${s.queue.peak} completed=${s.metrics.completed}`);
}

// db outage: circuit opens, no commits while down, recovery
{
  const e = new Sim(5, 'database-outage');
  e.step(4000);
  const down = !e.primary.up && e.breaker.state === 'open' || !e.primary.up;
  const commitsDown = e.primary.commits;
  e.step(14000); // recover at 15000
  e.step(12000);
  all &= check('db outage circuit+recovery', down && e.primary.up && e.primary.commits >= commitsDown,
    `downSeen=${down} up=${e.primary.up} breaker=${e.breaker.state} commits ${commitsDown}→${e.primary.commits}`);
}

// stale replica: stale reads then converge
{
  const e = new Sim(8, 'stale-replica');
  e.step(8000);
  const staleMid = e.replica.staleReads;
  e.step(10000);
  const s = e.snapshot();
  all &= check('stale replica reads then lag clear', staleMid >= 0 && s.replica.lagMs === 0,
    `staleReads=${s.replica.staleReads} lag=${s.replica.lagMs} pending=${s.replica.pendingOps}`);
}

// pause via frameAdvance
{
  const e = new Sim(1, 'healthy');
  e.paused = true;
  const { frameAdvance } = new Function(script + '\nreturn { frameAdvance };')();
  const t0 = e.now;
  frameAdvance(e, 1000);
  all &= check('paused animation does not advance', e.now === t0, `now=${e.now}`);
}

console.log(all ? '\nSCENARIO CHECKS PASS' : '\nSCENARIO CHECKS FAIL');
process.exit(all ? 0 : 1);
END

